window.ATLAS_I18N_STORIES={"lissandra-color-story":["วีรชนแห่งฟรอสท์มูน","วีรชนคือบุคคลใดก็ตามที่ยอมกระทำสิ่งที่พึงต้องกระทำ"],"rise-with-me":["เฉิดฉายเคียงกัน",""],"kennen-color-story":["ระหว่างแสงสว่างและเงามืด","เคนเนนไม่ได้ชะลอความเร็วเลยตั้งแต่ออกมาจากมหาวิหารโคเอชิน"],"braum-color-story":["หลุมศพของเจ้าโทรลหนุ่มน้อย","&apos;&apos;อยากฟังนิทานก่อนนอนไหมจ๊ะ?&apos;&apos;"],"gnar-color-story":["นักล่าที่ถูกล่า","ผืนป่ามิเคยให้อภัยผู้ไม่ระวังตน ทุกกิ่งไม้ที่หักบอกเรื่องราวเสมอ"],"sion-color-story":["ในห้วงความคิดของคนคลั่ง","เลือด"],"bilgewater-story":["Burning Tides","ที่นี้คือท่าชำแหละปลาแห่ง Rat town และกลิ่นของที่นี้ก็เลวร้ายเหมือนชื่อ"],"karthus-color-story":["พิธีฝังศพที่ทะเล","ผืนน้ำทะเลเรียบเหมือนผิวกระจกและดำสนิท จันทร์เต็มดวงลอยอยู่ต่ำตรงขอบฟ้าเหมือนที่เป็นมาหกคืนแล้ว เสียงลมหวีดหวิดไม่เบานักพัดอยู่ เพลงสวดดังแว่วมาจากที่ไหนก็ไม่มีใครรู้ได้ Vionax ล่องเรือแถว Noxus มานานพอจะรู้ว่าสภาพทะเลแบบนี้บ่งบอกถึงลางร้าย เธอยืนบนดาดฟ้าทางหัวเรือ Darkwill ใช้กล้องส่องดูสิ่งที่อยู่ในทะเล มองหาอะไรก็ตามที่เอามาหาตำแหน่งตอนนี้ได้"],"kalista-color-story":["คำอ้อนวอน","นกรบหญิงยืนอยู่ท่ามกลางซากบ้านที่ถูกเผาของเธอ ทุกสิ่งและทุกคนที่เคยสำคัญกับเธอนั้นได้จากไปแล้ว เธอมีแต่ความโศกเศร้ามากเกินประมาณได้… กับความเกลียดชัง ในตอนนี้ มีแต่ความเกลียดชังเท่านั้นคอยผลักดันเธอ"],"thresh-color-story":["การกวาดเก็บ","เสียงครูดลากโซ่เหล็กน่าสยดสยองลอยสะท้อนไปทั่วทุ่งกว้าง ข้างนอกมีหมอกผิดธรรมชาติบดบังจันทราและดวงดาราจนมองไม่เห็น เสียงร้องของแมลงพลันเงียบลง"],"hecarim-color-story":["ไร้คนรอด","คลื่นยะเยือกสาดซัดกระแทกเข้าหาชายฝั่งเปล่าเปลี่ยวแดงฉานไปด้วยเลือดของผู้คนที่ Hecarim ฆ่าทิ้งอย่างทารุณ ส่วนพวกมนุษย์ที่เขายังไม่ได้ฆ่า ถอยหนีไปในชายหาดด้วยความหวาดกลัว พวกมันเปียกโชกจากหยาดฝนสีดำ และพายุเมฆเริ่มบ้าคลั่งยิ่งขึ้นจาก the mourning heart ของเกาะ เขาได้ยินพวกมันตะโกนหากัน คำศัพท์ที่ใช้ในการต่อสู้ดังรัวก้องในลำคอ แม้เขาไม่รู้จักแต่กลับเข้าใจความหมายดี พวกมันคิดว่าพวกมันจะมีชีวิตรอดกลับไปที่เรือของพวกมัน จริงอยู่ที่พวกมันพอมีฝีมือ พวกมันเคลื่อนตัวเป็นกลุ่มพร้อมทั้งประสานโล่ไม้เข้าไว้ด้วยกัน แต่พวกมันก็แค่มนุษย์ และ Hecarim ชื่นชอบเนื้อที่เหม็นไปด้วยความกลัวของพวกมันนัก"],"kindred-color-story":["ป่าเพื่อต้นไม้","สำหรับพวกเขาแล้ว การสู้รบนั้นเปรียบเสมือนงานเทศกาล ช่างเป็นชีวิตที่สนุกสนาน มีคนมากมายให้ฆ่า มีคนมากมายให้ล่า! Wolf เร่งฝีเท้าท่ามกลางหิมะ ขณะที่ Lamb เริงระบำอย่างอ่อนช้อยจากคมดาบไปสู่ปลายหอกโดยที่เสื้อคลุมสีซีดของนางไม่เปื้อนคราบเลือดจากการสังหารเลยแม้แต่หยดเดียว"],"kindred-good-death-story":["A Good Death","Magga กำลังจะตายเป็นครั้งที่สิบสี่ เธอได้กัดผลแอปเปิ้ลเน่าผุอีกครั้ง เนื้อผลไม้ที่เน่าเปื่อย ทำให้เธอติดเชื้อจากซากเน่าดังที่เคยเกิดขึ้นทุกครั้ง นักแสดงสาวออกท่าทางการล้มตายพร้อมตะโกนคำพูดสุดท้ายให้ทุกคนได้ยิน"],"shadow-and-fortune-story":["Shadow and Fortune","Jackdaw คนหนึ่งถูกพวก Butcher Blades จับมาเสียบด้วยมีด marlinspike มีดเล่มนั้นยังเสียบคากรามเขาอยู่ มันแขวนร่างเขาให้เป็นอาหารของพวกสัตว์กินซาก นับเป็นศพที่สิบเจ็ดแล้วในคืนนี้ที่ชายสวมหมวกคลุมเห็น"],"illaoi-color-story":["ภาระ","&#x201C;ผู้กุมสัจธรรม นี่คือสาเหตุที่เราต้องถอยกลับไปที่ Buhru เราไม่อาจช่วยชาว เพลังกิได้&#x201D; พระราชาคณะกล่าว สาวร่างยักษ์ฉีกยิ้มด้วยความปลื้มปิติที่จะได้ไปจาก Bilgewater เสียที"],"poppy-color-story":["มือสังหาร","Poppy ไม่มีเรื่องใดๆ กับหมาป่าหนาม ยกเว้นเรื่องที่มันกำลังจะขย้ำเธอ จมูกและปากของมันสีแดงฉานจากเหยื่อรายก่อน และ Yordle ผู้นี้ก็ไม่อยากเสี่ยงที่จะเป็นรายถัดไป เธอกำลังออกไล่ตามมือสังหารสัตว์ประหลาด และเธอยังไม่คิดที่จะตายก่อนที่จะได้พบกับชายผู้นั้นและตัดสินว่าเขาคู่ควรหรือไม่"],"shen-color-story":["ผู้เป็นกลางอย่างแท้จริง","เขาคุกเข่าลงบนชายหาดเพื่อดูสภาพศพที่ชาวบ้านนำขึ้นมา ร่างของชายคนนั้นขาดสองท่อนตรงด้านล่างชายโครง เครื่องในที่ยังหลงเหลืออยู่ห้อยลงจากส่วนอกสีซีดที่ขึ้นอืด"],"taric-color-story":["แขกไม่ได้รับเชิญ","ข้ามองออกไปยังทุ่งซึ่งเคยเขียวขจี ตอนนี้พังทลายและเต็มไปด้วยร่องรอยจากศึกการต่อสู้"],"leona-color-story":["ผู้นำพาแสงสว่าง","ฝูงโจรได้บุกเข้าปล้นก่อนรุ่งสาง ชายฉกรรจ์รูปร่างผอมปราดเปรียวดั่งหมาป่าห้าสิบคนในเกราะโซ่ปกคลุมด้วยขนสัตว์แปลกตาและถือขวานคมทื่อ ย่างก้าวของพวกเขาว่องไวเมื่อก้าวเข้าสู่หมู่บ้านตรงเชิงหุบเขา ผู้ชายเหล่านี้ได้ต่อสู้เคียงข้างกันดั่งพี่น้องมาเป็นปี ผู้ที่ใช้ชีวิตอยู่ในจังหวะการเต้นหัวใจระหว่างความเป็นและความตาย"],"diana-color-story":["ภารกิจในหนึ่งคืน","กลางคืนเป็นช่วงที่ Diana ชอบที่สุดมาตั้งแต่ไหนแต่ไร แม้แต่เมื่อตอนยังเด็ก เป็นเช่นนี้มาตลอดตั้งแต่เธอโตพอจะปีนข้ามกำแพงวิหาร Solari ออกมาดูดวงจันทร์เคลื่อนผ่านหมู่ดาวบนผืนฟ้า เธอเงยหน้าเพื่อมองผ่านป่าทึบ ตาสีม่วงชำเลืองหาดวงจันทร์สีเงิน แต่เห็นเพียงแสงมัวผ่านเมฆครึ้มและกิ่งไม้หนา"],"aurelionsol-color-story":["รุ่งอรุณมีสองครั้ง","ดวงอาทิตย์อันคุ้นตาของดาวเคราะห์ดวงนี้ยังหลบอยู่หลังขอบฟ้า ผิวโลกหยาบและไร้ซึ่งความประณีตคลี่ตัวอยู่เบื้องหลัง ภูผาคดเคี้ยวเป็นกำแพงกั้น ยื่นยาวเหมือนนิ้วมือบนป่าไม้พุ่มเบื้องล่าง ปราสาท หรือสิ่งที่พวกมันเรียกว่าปราสาท ไม่ได้สูงตระหง่านค้ำอะไรทั้งนั้นนอกจากเนินเตี้ย ๆ ส่วนโค้งของดาวเคราะห์นี้จรดหมู่ดาวที่ขอบโลก ดูสงบและงดงาม มีเพียงผู้อาศัยเบื้องล่างไม่กี่คนเท่านั้นที่เคยได้เห็น พวกมันอยู่กันกระจัดกระจายบนโลกนี้ ไล่ไขว่คว้าความรู้อย่างหน้ามืดตามัว ไม่ใช่เรื่องน่าแปลกใจที่พวกมันพ่ายแพ้ แต่ยังไม่อาจเข้าใจสภาพของตนได้"],"reksai-color-story":["Sai Khaleek","เด็กหนุ่มหกคนกับอูฐหนึ่งตัว และเด็กเหล่านั้นนำมาใช้แทนได้ในราคาถูกกว่า บางคนเป็นเด็กกำพร้าและทาสที่หนีมา แต่ส่วนใหญ่ถูกทิ้งไว้ &#x2014; เด็กวัยรุ่นที่ถูกทอดทิ้งโดยครอบครัวที่ยากจนเกินกว่าจะเก็บพวกเขาไว้ เมื่อ เมื่อตอนที่ Shahib เสนองานให้เขาทำนั้น Jaheje ไม่ได้กินอะไรมาหลายวันแล้ว"],"azir-color-story":["เกิดขึ้นแล้ว","Azir เดินไปตามเส้นทางจักรพรรดิที่ปูลาดด้วยทองคำ รูปปั้นสูงตระหง่านของผู้ครอง Shurima คนก่อนๆ บรรพบุรุษเขา คอยเฝ้ามองแต่ละย่างก้าว"],"bird-and-branch-story":["นกและกิ่งไม้","“พลังนั้นของเจ้ามีไว้เพื่อทำลาย เจ้าไม่อยากใช้มันรึ? ก็ได้ ให้มันเป็นหินถ่วงเจ้าจมลงไปเถอะ”"],"xerath-color-story":["ปลดพันธนาการ","ช่วงเวลาในตอนนี้"],"nasus-color-story":["OUROBOROS","Nasus ท่องไปในยามราตรี ไม่ยินดีจะเผชิญหน้ากับดวงอาทิตย์ เด็กชายตามไปโดยที่ยังตื่นอยู่"],"renekton-color-story":["ความมืดมาเยือนอีกครั้ง","ข้าคือพระเจ้าหรือ?"],"sivir-color-story":["น้ำ","ลำคอของ Sivir รู้สึกราวกับถูกเคลือบไว้ด้วยแก้วแตกๆ ชั้นหนึ่ง ริมฝีปากแห้งแตกของเธอแสบร้อน สายตาปฏิเสธที่จะจดจ้อง ข้าได้ให้เวลาพวกเขาเดินจากไปมากเกินพอเสียอีก"],"amumu-color-story":["ความโลภ และน้ำตา","“พวกพระเจ้าพิโรธและเขย่าผืนแผ่นดิน จนรอยแตกเกิดขึ้นบนโลก“ Khaldun ผู้เฒ่าเล่าออกมาด้วยใบหน้าที่เต็มไปด้วยรอยตีนกาที่กระทบกับแสงจากกองไฟ “มันเป็นหนึ่งในรอยแตกที่ชายหนุ่มผจญภัยเข้าไป เขาได้ค้นพบหนทางลับเข้าสู่สุสาน มันถูกซ่อนจากพวก Jackalไม่รู้ว่านานเท่าใด แต่ชายหนุ่มผู้มีลูกน้อยที่ต้องเลี้ยงดูและภรรยาที่ต้องเอาใจ จึงยอมเสี่ยงภัยเข้าไป เพราะถูกล่อลวงด้วยโอกาสที่อยู่ตรงหน้า”"],"rammus-color-story":["คาราวานขึ้นเหนือ","“พวกพระเจ้าพิโรธและเขย่าผืนแผ่นดิน จนรอยแตกเกิดขึ้นบนโลก“ Khaldun ผู้เฒ่าเล่าออกมาด้วยใบหน้าที่เต็มไปด้วยรอยตีนกาที่กระทบกับแสงจากกองไฟ “มันเป็นหนึ่งในรอยแตกที่ชายหนุ่มผจญภัยเข้าไป เขาได้ค้นพบหนทางลับเข้าสู่สุสาน มันถูกซ่อนจากพวก Jackalไม่รู้ว่านานเท่าใด แต่ชายหนุ่มผู้มีลูกน้อยที่ต้องเลี้ยงดูและภรรยาที่ต้องเอาใจ จึงยอมเสี่ยงภัยเข้าไป เพราะถูกล่อลวงด้วยโอกาสที่อยู่ตรงหน้า”"],"rg-shurima-story":["Bloodline","Taliyah แทบลืมไปแล้วว่าตนคิดถึงไอร้อนระอุของ Shurima มากเพียงใด ทั้งเหงื่อออก ทั้งแรงผลักจากคนนับหลายร้อยที่เบียดเสียดกัน เสียงสบถด่า ต่อราคา พูดคุยกันอย่างดุเดือดและรัวเร็วจนคนนอกคิดว่ามีเรื่องทะเลาะกันอยู่บ่อยครั้ง"],"taliyah-color-story":["เสียงสะท้อนในศิลา","Taliyah กำลังหนีจากพายุทรายเมื่อเธอสังเกตเห็นสายน้ำเป็นครั้งแรก ในช่วงแรก ๆ มันยังแผ่วจางอยู่ เป็นแค่ความชื้นที่เธอรู้สึกได้ตอนยกหินขึ้นมาจากใต้ทรายลึก ขณะเธอเข้าใกล้เขต Shurima เก่ามากขึ้น รอยเปียกหยดลงมาจากหินก้อนใหม่แต่ละก้อนราวกับกำลังร่ำไห้ Taliyah รู้ว่าศิลาต่างมีเรื่องจะเล่าขณะเธอเร่งรุดข้ามทะเลทราย แต่เธอไม่ได้มีเวลาพอรับฟังเพื่อให้รู้ว่าพวกมันคือหยาดน้ำตาแห่งความสุขหรือความเศร้ากันแน่"],"tristana-color-story":["ราตรีเงียบงัน","เสียงกิ่งไม้ในกองไฟแตกดังเปรี๊ยะช่างฟังดูไพเราะ แสงอุ่นของเปลวเพลิงส่องไสวไปทั่วผืนป่า Tristana เอนกายลงนอนโดยใช้เป้ต่างหมอน แหงนมองดาวหางซึ่งพาดผ่านผืนฟ้าที่ดารดาษไปด้วยดวงดาว เห็นแสงระยิบระยับส่องประกายหลังเงาของกิ่งต้นเบิร์ชและต้นโอ๊ค เธอรู้มาจากหนังสือเก่าๆที่อยู่ในห้องแล็ป Heimerdinger ว่าพวกมนุษย์มักชอบตั้งชื่อให้กลุ่มดาว แต่เธอคิดว่ามันคงจะสนุกกว่าถ้าพวกเขาจะตั้งชื่อให้กับสิ่งประดิษฐ์ของเธอบ้าง"],"ryze-color-story":["เพื่อนเก่า","Ryze คงจะหนาวเหน็บหากร่างกายของเขาไม่คุกรุ่นไปด้วยพลังงานที่มาจากความร้อนรนกระวนกระวายใจ ในวันนั้น ความเกรี้ยวกราดของ Freljord ไม่อาจทำอะไรต่อจิตใจอันคุกรุ่นของเขาได้เลย เขาไม่หวาดกลัวแม้เสียงคำรามของยักษ์โทรลน้ำแข็งที่หิวโหยจากระยะไกล เขามาเพื่อปฏิบัติภารกิจให้สำเร็จ แม้จะไม่ใช่สิ่งที่เขาชอบ แต่ก็เป็นที่ภาระหน้าที่ที่ต้องทำ และมันก็เป็นภารกิจที่เขาเองก็หลีกเลี่ยงไม่ได้อีกต่อไป"],"kled-color-story":["พื้นที่ที่ดราคาล็อปส์เดินทางผ่านไป","ทุ่งหญ้าสเตปป์ทางตอนเหนือไม่ใช่สถานที่ที่เจ้าจะเจอชุดชั้นในแฟนซีหรือโถฉี่ทองคำได้ มันเป็นแดนทุรกันดาร ไม่มีสิ่งใดอยู่ที่นั่นนอกจากพวกหัวขโมยป่าเถื่อน หญ้าพิษ และสายลมที่เกรี้ยวกราด ถ้าอยากมีชีวิตรอด เจ้าต้องกินก้อนหินและขับถ่ายออกมาเป็นลาวา และข้าก็คือไอ้เบื๊อกที่ทรหดที่สุด โหดร้ายที่สุด และเลือดเย็นที่สุดในดินแดนเหล่านี้ ดังนั้นข้าจึงคิดว่าที่ราบเหล่านี้เหมาะจะเป็นดินแดนของข้า"],"yorick-color-story":["พิธีกรรมสุดท้าย","“ช่วยข้าด้วย...” เสียงจากคนเรือแตกร้องเรียก"],"shadow-isles-story":["The Princeling’s Lament","จงขัดถูตะไคร่น้ำจากบัลลังก์"],"evelynn-color-story":["ดอกเดซี่ที่สูงที่สุด","Evelynn หลบเร้นกายผ่านถนนที่เปียกแฉะ เงาของตัวเธอทาบทับปนเปไปกับเงาของค่ำคืน ดวงตาของเธอแวบวาบสะท้อนความเศร้าหมองข้างใน ต้องมีสายตาเฉียบคมพอเท่านั้นจึงจะสังเกตเห็น คนเมา กะลาสี และโสเภณี พูดคุยกันในทางสัญจรใกล้เคียง ต่างหัวเราะร่า โดยไม่ระวังตัวเอาเสียเลยว่ากำลังถูกจ้องมองจากปิศาจในเงามืด ในทางกลับกัน ปิศาจกลับมองเห็นพวกเขาได้อย่างชัดเจน และตัดสินพวกเขาด้วยสายตาอันหยั่งรู้"],"maokai-color-story":["ดอกไม้ราตรี","ลมหนาวกรีดผ่านรอยแตกบนเปลือกตัวข้าเสียงดังหวีดหวิว ข้าหนาวสั่น แขนขาข้าลืมความอบอุ่นของฤดูร้อนไปนานมากแล้ว"],"elise-color-story":["ดุจเส้นใยไหม","ระยะเวลาหลายสัปดาห์ของการเดินทางกลางมหาสมุทรทำให้มาร์คัสรู้สึกวิงเวียนและอ่อนแรง เขาจึงดีใจเหลือเกินเมื่อได้กลับมาอยู่บนบกอีกครั้ง เส้นทางจากชายหาดทรายดำนั้นทั้งลื่นและมีคราบมันทำให้เดินยากยิ่ง ต้นไม้หงิกงอที่ขึ้นอยู่ทั้งสองฟากนั้นอยู่ในสภาพไม่ชวนมอง ยางไม้สีเหลืองไหลย้อยออกมาจากเปลือกไม้สีดำตรงจุดที่ดูเหมือนถูกฉีกตะกุยโดยสัตว์ที่ตื่นกลัว แสงละมุนทอประกายลอดหมู่ต้นไม้ลงมาและพลิ้วเคลื่อนดูดั่งลูกไฟวิญญาณที่ลอยอยู่เหนือหนองน้ำและดึงดวงวิญญาณที่ไม่ทันระวังให้จมดิ่งสู่หายนะ ตามกิ่งไม้มีสิ่งที่ดูเหมือนเศษผ้ามัสลินรุ่งริ่งห้อยแขวนอยู่ มาร์คัสต้องใช้เวลาสักพักจึงจะดูออกว่ามันคือใยแมงมุม"],"ivern-color-story":["ของขวัญจากอสรพิษ","สำหรับคนส่วนใหญ่แล้ว เวลาหนึ่งร้อยปีนับว่าช่างยาวนานยิ่งนัก ในหนึ่งศตวรรษ คนหนึ่งคนสามารถสำรวจโลกทั้งใบ พบปะผู้คนนับพัน หรือสร้างสรรค์งานศิลป์นับไม่ถ้วน ด้วยเหตุนี้ ใครๆ จึงสามารถคะเนได้ง่ายๆ ว่าการยืนอยู่กับที่เป็นเวลามากกว่าหนึ่งศตวรรษนั้นเป็นการเสียเวลามากแค่ไหน ทว่าสำหรับ Ivern Bramblefoot แล้ว เวลาหนึ่งศตวรรษที่เขายืนอยู่กับที่ได้สร้างคุณประโยชน์เหนือกว่าที่ใครจะคาดคิด"],"fiora-color-story":["เรื่องของเกียรติยศ","ชายที่ Fiora กำลังจะฆ่ามีนามว่า Umberto ลักษณะท่าทางของเขาคือเป็นบุรุษที่มั่นใจในตนเองมาก นางดูเขาพูดคุยกับชายสี่คน แน่นอนว่าพวกเขาจะต้องเป็นพี่น้องกัน ทั้งห้าคนต่างก็มีความมั่นใจเกินตัวและกำลังแต่งตัวเสริมหล่อกันอยู่ พวกเขาทำเหมือนกับว่าการแสดงตัวในหอชุมนุม Blades เพื่อรับคำท้าจากนางนั้นเป็นเรื่องที่น่าขายหน้า"],"leesin-color-story":["ทุกสิ่งที่ระยิบระยับ...","รากไม้เก่าแก่ ต้นไม้ที่คดเคี้ยว และเถาวัลย์ที่มีใบหนาเกาะกับโขดหินแทบจะบดบังทางเดินผ่านป่าอันเขียวชอุ่ม ชายสามคนเสียเหงื่อด้วยการฟันทางของตัวเองเข้าไป แรงขับเคลื่อนของพวกเขาคือหัวใจที่เต็มไปด้วยความตะกละ และความฝันที่จะได้ครองทรัพย์สินนับไม่ถ้วน ป่าแห่งนี้เป็นอุปสรรคต่อพวกเขาตลอดหกวันที่ผ่านมา แต่ในขณะนี้ พวกเขาก็ได้มาอยู่ตรงหน้าวิหารกลางพงป่าที่ตามหาแล้ว ด้านหน้าของวิหารเป็นชิ้นงานี่แกะสลักลงบนหินขนาดมหึมาที่โผล่พ้นดิน มีดอกไม้สีแดงและน้ำเงินบานอยู่รอบหินก้อนนั้น รูปปั้นอันสงบเงียบจำนวนหนึ่งตั้งอยู่ในซุ้มสีทอง พร้อมด้วยพวงดอกกล้วยไม้สีเหลืองทองที่พันอยู่ทั่วชายคา"],"ezreal-color-story":["The Elixir of Uloa","หลังจากต้องเดินผ่านป่าร้อนชื้นอบอ้าวเป็นเวลาหลายชั่วโมง อากาศเย็นสบายของสุสานใต้ดินนี้ถือเป็นพรจากสวรรค์ แน่นอนว่า ความตายที่อาจเกิดขึ้นได้รอคอยอยู่ทุกย่างก้าว แต่ความรุ่งโรจน์เองก็เช่นเดียวกัน"],"fiddlesticks-color-story":["เสียงหลอนจิต","มหากษัตริย์สิบองค์ทรงราชย์"],"cassiopeia-color-story":["สลัดคราบ","Cassiopeia เอนตัวอิงกับแนวหยักรอบดาดฟ้า ทอดสายตามองเหนือตรอกขดกับถนนที่มีคนแน่นขนัดของเมือง Noxus นางสวมชุดผ้าไหมโปร่งบางทิ้งตัวลงมา เปิดเผยส่วนสะโพก บริเวณที่ผิวอ่อนนุ่มรวมกับผิวหนังปกคลุมด้วยเกล็ดเรียงตัวคดเคี้ยวของงูหลอมรวมกัน ดูไม่สะทกสะท้านต่อลมเย็นยามค่ำคืน"],"jax-color-story":["ไม่มีผู้ใดผ่านได้","Jax นั่งไขว่ห้างอยู่กลางสะพานโดยวางด้ามหอกของเขาไว้บนเข่า Demacia ยังไม่เปลี่ยนไปมากนักนับตั้งแต่ครั้งสุดท้ายที่เขาสัญจรผ่านทางนี้ แต่นั่นก็ไม่ได้ทำให้เขาประหลาดใจ&#x2019; ผู้คนของดินแดนแห่งนี้ปกป้องชายแดนของตนอย่างแข็งขันจนกลายเป็นนักสู้ที่มีฝีมือค่อนข้างดี ก็แค่บางคนน่ะ เขาคิด พร้อมกับเช็ดคราบเลือดออกจากส่วนหัวของเสาไฟที่ส่องประกายอ่อนๆ เขาสะบัดหยดเลือดข้ามกำแพงลงสู่แม้น้ำด้านล่าง จากนั้นก็ล้วงเข้าไปในเสื้อคลุมยาวเพื่อหยิบไข่ต้มสุกออกมากินเป็นใบที่สามของวันนี้ Jax กะเทาะไข่กับหินบนสะพานและค่อยๆ แกะเปลือกออก ขณะเดียวกันก็ได้ยินเสียงเหล่านักรบที่อยู่ปลายสะพานซึ่งกำลังตัดสินใจอยู่ว่าพวกมันคนใดจะเป็นคู่ต่อสู้คนต่อไปของเขา"],"blitzcrank-color-story":["ดนตรีประสาน","เครื่องยนต์ขนาดใหญ่ของ Rising Howl ส่งเสียงคำรามตรงหน้าผม เกียร์หมุนวนไปเรื่อยๆ เพื่อทำให้ชิ้นส่วนโลหะทำงาน บางคนบอกว่าชื่อของ Howl มาจากหมาป่าเหล็กบริสุทธิ์ที่ร้องคำรามที่จุดสูงสุดของลิฟท์ไฮดรอลิกผสม Hextech บางคนก็สาบานว่ามีผีของของทาสที่สวมใส่ผ้าคลุมหน้าสีดำหลอกหลอนตู้ลิฟต์ เมื่อ Howl ส่งตัวของเขาขึ้นและพรากเขาจากคนรักของเขาที่เมือง Zaun เสียงร้องของเขาทำให้กลไกเหล็กถึงกับสั่นสะเทือน ชาว Piltover หลายคนที่เชื่อมั่นในการตัดสินใจของตนเอง คิดว่าชื่อของมัน ไม่มีอะไรมากไปกว่าลมเย็นจัดที่หวีดหวิวระหว่างรอยแยกบนน้ำแข็งที่อยู่ใต้เมือง"],"zaun-cityironglass":["เมืองแห่งเหล็กและกระจก","“เร็วเข้า Wyn!” Janke ตะโกน “Rising Howl กำลังมา!”"],"camille-color-story":["จิบน้ำชากับโฉมงามสีเทา","เสียงแรกที่ผมได้ยินคือเสียงเหล็กแหลมขูดกับหิน สายตาของผมพร่ามัว วิสัยทัศน์ของผมยังคงแหวกว่ายในความมืดมัว แต่เสี้ยวหนึ่งของจิตใจของผมรับรู้เสียงนั่นได้ชัดเจน เสียงคมมีดที่ครูดกับหินเปียก เสียงนั้นเป็นเสียงเดียวกับช่างของผมยามที่เขาเลือกหินที่จะตัดมาจากหน้าผา มันทำให้ผมต้องขบฟัน หมอกในหัวสมองของผมจางลง แต่มันก็ทิ้งผมไว้กับความคิดน่าตระหนกเมื่อผมพยายามฝืนเชือกที่ผูกมือผมไว้"],"warwick-color-story":["หากพวกเขาวิ่ง","ผมพบเธอใกล้ถนน Black Lanes ที่ซึ่งพ่อค้าแม่ค้าและขโมยต่างกันทำธุรกิจของตัวเอง สินค้าทุกชิ้นมีไว้ขาย แต่ทุกอย่างก็ถูกขโมยไปเรียบ ผมสามารถฆ่าโจรทั้งหมดพวกนั้นได้"],"caitlyn-color-story":["ความตื่นเต้นของการไล่ล่า","แม้ว่าระฆังจะดังไปแล้วสามรอบ หลังจากที่ Sun Gate ได้ปิดลง Piltover ก็ยังคงเต็มไปด้วยชีวิตชีวา คนพวกนี้กำลังขวางทางเธออยู่ในตอนนี้ Caitlyn วิ่งมาตามเส้น Mainspring Crescent เธอขอทางแทรกตัวไประหว่างพวกสำมะเลเทเมาที่ทยอยเดินทอดน่องกันอยู่ตามถนนที่เต็มไปด้วยร้านกาแฟและร้านอาหาร คนกำลังทยอยออกมาจากร้านอาหารและโรงหนังใกล้ ๆ กันด้านใน Drawsmith Arcade ถนนสายนี้จึงกำลังจะชุลมุนไปด้วยผู้คนมากขึ้น หากพวกเขาไม่สามารถไปถึงตัว Devaki ได้ในเร็ว ๆ นี้ พวกเขาจะคลาดกัน"],"jinx-color-story":["ยอดนักล่มงานวิวาห์","Jinx เกลียดกระโปรงชั้นใน"],"drmundo-color-story":["ปลอดภัยใกล้มือหมอ","นี่มันก็ผ่านมาสักพักแล้ว มุนโด้คิดพลางลูบลิ้นสีม่วงอันใหญ่โตที่ห้อยออกมาจากปากเขาราวกับอาชญากรที่ถูกประหารและห้อยต่องแต่งอยู่ตรงแท่นแขวนคอ นับจากครั้งสุดท้ายที่มุนโด้ออกไปรักษาคนไข้นอกสถานที่"],"orianna-color-story":["Fieram","Orianna เดินผ่านบริเวณงานเทศกาลที่ว่างเปล่าเนื่องจากอยู่ในเวลากลางคืน เทศกาล Sir Feisterly’s Fantastical Fair จะเปิดประตูให้ชาวเมือง Zaun เข้ามารับความบันเทิงเพียงแค่สองครั้งต่อปีเท่านั้น และ Oranna ก็ไม่อยากพลาดโอกาสที่จะได้สัมผัสกับความมหัศจรรย์ เธอเฝ้ารอตลอดทั้งวันจนทุกคนกลับไปจนหมด รวมทั้งเสียงหัวเราะอึกทึกและเสียงดนตรีก็เงียบลง มีเพียงเสียงท่อเครื่องปั๊มไอน้ำจากเขตเคมีภัณฑ์ที่อยู่ใกล้เคียงเท่านั้นที่รบกวนความเงียบสงัดนี้ เศษขยะกระจายเกลื่อนพื้น ไม่ว่าจะเป็นสายรุ้งประดับหลากสีสันและลูกโป่งสีสดที่ปะปนกับกระดาษไขยับย่นซึ่งเคยเป็นห่อขนมอบไส้แยมรสหวาน"],"ekko-color-story":["บทเพลงกล่อม","วันนั้นเป็นวันที่รู้สึกยาวนานราวสัปดาห์"],"janna-color-story":["หายใจลึก","พวกเขาคิดว่า Zaun คือเมืองของพวกขี้แพ้"],"viktor-color-story":["บ้านเหนือ Emberflit Alley",""],"heimerdinger-color-story":["จากบันทึกประจำวันของศาสตราจารย์ Cecil B. Heimerdinger","10.14"],"zac-color-story":["การปกป้อง","ช่วงเวลาที่น่ายินดีที่สุดตั้งแต่ห้าถึงหกโมงเย็น นั่นคือช่วงเวลาที่ฉันชอบ มันเป็นเวลาที่ชาวเมืองส่วนใหญ่ใน Factorywood ทำงานเสร็จ พวกเขาจะเหนื่อยล้า ไม่อยากทำอะไรอีกในวันนั้น พวกเขาทิ้งงานไว้เบื้องหลัง อาหารร้อนๆ และบ้านรอพวกเขาอยู่เบื้องหน้า ชาวเมืองที่นี่นิสัยดี และผมก็มักจะรู้สึกดีที่ได้บีบร่างเจลาตินของตัวเองไปตามรอยแยกของหน้าผาที่ระหว่างหินแต่ละก้อนรอบๆ Factorywood ผมสัมผัสได้ถึงความรักจากชายคนหนึ่งซึ่งกลับบ้านไปหาลูกชายที่เพิ่งเกิดใหม่ ผมเพลิดเพลินไปกับการชมคู่สมรสตั้งหน้าตั้งตารอมื้อเย็นที่แสนจะโรแมนติกในตลาด Boundary"],"piltover-progress-day":["วันแห่งความก้าวหน้า","Tamara ฝืนตัวเองให้ตื่นเช้า ซึ่งเป็นนิสัยที่ฝึกค่อนข้างง่ายถ้ามีผืนดินเป็นเตียงและใบไม้ที่ร่วงกองบนพื้นเป็นผ้าห่ม แต่มันก็กลายเป็นเรื่องที่ยากทันทีถ้าฟูกนั้นทำมาจากขนเป็ดและผ้าปูถักทอมาจากฝ้ายนุ่ม ผ้าม่านถูกดึงออก และแสงอุ่นก็สาดส่องบนพื้นของห้องพักชั้นสามของเธอ เธอเคยปิดม่านนี้ในคืนแรกที่อยู่ใน Piltover แล้วเธอหลับนานจนเลยรุ่งเช้าไปสองชั่วโมง ซึ่งทำให้เธอกังวลใจมากเสียจนทำให้เธอไม่ปิดม่านนั้นอีกเลย"],"jayce-color-story":["การซ่อมด่วน","แม้แต่คนโง่ก็คาดการณ์ได้ว่า Viktor จะโจมตีกลับได้ทุกเมื่อ ถ้าไม่ใช่คนโง่ ก็อาจคาดการณ์ถึงวันและเวลาที่จะมีการโต้กลับได้"],"twitch-color-story":["อย่าเข้าต่อสู้โดยลำพัง","เอกสารรายงานอุบัติการณ์ H.I.V.E."],"vi-color-story":["การสอบสวน 101","Vi อ้าปากหาวในขณะที่เธอเดินผ่านห้องโถงเลี่ยมทองในใจกลาง Hall of Law แห่งเมือง Piltover พระอาทิตย์เพิ่งขึ้นยังไม่ถึงชั่วโมง และสถานที่แห่งนี้เงียบสงัด คนเมายังคงหลับอยู่ในห้องขังแห่งความอับอาย และเธอได้ยินว่ามีพวกอันธพาลเสริมร่างกายด้วยเคมีในห้องขังที่ลึกเข้าไปและได้รับการปกป้องอย่างแน่นหนา เธอกะว่าจะถามทีหลัง เผื่อว่าเธอจะได้ให้ข้อมูลได้ว่าพวกเขามาทำอะไรที่ Piltover"],"camille-weakest-heart":["หัวใจที่อ่อนแอ","“คุณน่าจะฆ่านางซะ”"],"singed-thenightmare-story":["วิศวกรรมกำเนิดฝันร้าย","เก็บตัวอย่างโจรกระจอกที่ซ่อนตัวท่ามกลางหมู่ประชากรและแสร้งความเป็นมนุษย์ มีเพียงแค่คนที่ได้รับการฝึกฝนเป็นอย่างดีเท่านั้นที่จะสามารถมองเห็นปีศาจที่หลบซ่อนอยู่ภายใน รอการปลดปล่อยออกมา ข้าจะปฏิเสธความต้องการนั้นได้อย่างไร หากงานของข้าไม่ใช่การพยายามเปิดเผยความเป็นจริงที่ซ่อนอยู่ในชีวิตผ่านทางวิทยาศาสตร์แล้ว จะเป็นอะไรได้อีก ต้องใช้ยาสลบถึงสองขนานกว่าจะล้มมันได้ ดื้อดึงยิ่งนัก แต่ก็เป็นคุณลักษณะที่จำเป็นเพื่อจะรอดจากตัวกระตุ้นอันยิ่งใหญ่ที่เรียกว่าความเจ็บปวด และกระตุ้นการกลายพันธุ์ การเปลี่ยนแปลงโครงสร้างนี้จะทำให้มันกลายเป็นนักล่าที่มีคุณสมบัติผิดมนุษย์ และทั่วทั้งเมือง Zaun ก็จะกลายเป็นถิ่นล่าของมัน"],"shyvana-color-story":["สัตว์ร้ายมีปีก","ด้วยหน้าที่ของชาว Demacia ที่รวมเข้าความป่าเถื่อนของพลังมังกร นั่นทำให้เหล่าศัตรูของเธอไม่มีโอกาสเลย"],"jarvaniv-color-story":["งาช้าง มะเกลือ แจสเปอร์","กลุ่มก้อนความหายนะที่เคลื่อนตัวเข้าหาหมู่บ้านเล็กๆเหล่านั้ หมายถึงความตายของพวกเขา แต่เมื่อองค์ท่าน Jarvan มาเยือน มันจะมลายหายไป"],"garen-color-story":["ทหารกล้ากับแม่เฒ่า","หญิงแห่งศิลาจะคอยนำพาตัวทหารไป และในครั้งนี้เธอจะนำพา Garen กับดาบยักษ์ของเขาไปด้วย"],"quinn-color-story":["กฎในการเอาตัวรอด","พื้นที่ป่าของ Demacia ก็ไม่มีช่องว่างให้พวกหัวขโมยจาก Nexus อยู่ได้ แต่ Quinn กลับได้พบกับคนที่คาดไม่ถึง"],"for-demacia":["เพื่อเดมาเซีย","ครั้งล่าสุดที่ลักซ์เดินทางขึ้นเหนือไปฟอซแบร์โรว์นี่มันผ่านมานานเท่าไรแล้วนะ? นางไม่แน่ใจ แต่หลายปีแล้วแน่ๆ"],"flesh-and-stone":["เนื้อและหิน","สาวน้อยที่รู้สึกอายเพราะพลังที่เธอมี กับยักษ์ศิลาที่อยากสอดรู้สอดเห็นเรื่องต่างๆ หรือนี่จะเป็นการจับคู่ที่สมบูรณ์แบบ"],"lux-color-story":["แสงสุดท้าย","หลังจากเกิดเหตุการณ์ภัยพิบัติ Lux ยอมเอาตัวเข้าไปเสี่ยง เพื่อช่วยเหลือเหล่าทหารที่ได้รับบาดเจ็บ"],"galio-color-story":["วีรบุรุษฟื้นชีพ","พลังเวทมนตร์คือสิ่งที่ทำให้ยักษ์ใหญ่ฟื้นกลับมา แล้วส่งเขามาซัดกลับอีกตังหาก เพราะเขาก็มีพลังเช่นกัน"],"velkoz-color-story":["ความหิวกระหายที่แตกต่าง","ด้วยจุมพิตแด่ภรรยาและน้ำหนักของหอกบนบ่า ข้าได้กล่าวคำอำลาและเข้าร่วมกับพวกพ้องเดินทางจากหมู่บ้านไป รุ่งอรุณเพิ่งจะมาเยือนได้ไม่นาน แสงตะวันเพิ่งเริ่มทอตัวผ่านแนวแมกไม้ของผืนป่าแห่งโทโคกอลตอนที่พวกเราทั้งหกกำลังเดินทางไปสู่จุดสังเกตการณ์ที่ถนนดิน พวกเรามีสัมภาระติดตัวมาไม่มาก เนื่องจากการเฝ้ายามของพวกเราควรจะสิ้นสุดลงเมื่อดวงจันทร์ลอยขึ้นสู่ท้องฟ้าอีกครั้ง ก่อนที่เหล่าพลหอกชุดต่อไปจะมาแทนที่ โทโคกอลนั้นมีชายแดนติดกับน็อกซัส และความตึงเครียดที่เกิดขึ้นในระยะหลังนี้ก็กระตุ้นให้สภาขุนนางตื่นตัวที่จะคอยดูแลหอกทุกเล่มของพวกเขาให้แหลมคมอยู่เสมอ"],"ahri-garden-forgetting":["สวนแห่งการลืม","มีหลายอย่างที่ต้องสูญเสียให้แก่สวนแห่งนี้ จะเกิดอะไรขึ้นกับ Ahri ถ้าเธอยอมแพ้ให้แก่เธอ?"],"vastaya-field-journal":["การเดินทางในดินแดน Vastaya ของ Eduard Santangelo","สัตว์ประหลาดในนิยายที่มีเลือดมนุษย์? หรือเวทมนตร์ทางจิตวิญญาณจากชรเฝ่าโบราณกาล? การหาข้อมูลด้วยความอ่อนน้อมของฉัน จนต้องสะดุดเมื่อพบกับคำถามที่มากขึ้น... การค้นพบครั้งนี้จะเขย่าทุกประวัติการณ์ และขายดีตลอดกาล “Eduard Santangelo ผู้เป็นสุภาพบุรุษ นักสำรวจ และนักประวัติศาสตร์แห่ง Ionia ผู้ที่ค้นพบความมหัศจรรย์ของชาว Vastaya ในป่าลึกของ Ionia” ฉันได้ยินเสียงอึกทึกของพวกเขาลอยมาตั้งแต่อ่านหน้าแรกเลย"],"xayah-color-story":["Puboe Prison Break","Rakan น่ะแย่ที่สุด"],"rakan-color-story":["Nothing Rhymes with Tubebow","“จากหมู่บ้านข้างใต้ มีทางสองทางที่จะไปยังวัดที่เหมือนกับป้อมปราการนั่น” Xayah เริ่มพูด"],"rengar-prey":["เหยื่อ","ผู้ล่าคือผู้ดื่มกินบนความหวาดกลัวของเหยื่อ นักล่าที่ไร้ซึ่งความกลัว คือหนึ่งเดียวที่จะมีชีวิตอยู่ต่อไป"],"monkeyking-color":["ว่องไวและวู่วาม","เมื่อชีวิตแขวนอยู่อยู่เส้นด้าย คุณจะเลือกสิ่งใดระหว่าง เชื่องช้าและชาญฉลาด หรือว่องไวและวู่วาม"],"ahri-color":["การแลกเปลี่ยนที่ยุติธรรม","Ahri เดินทางพร้อมปิดบังตัวตนที่แท้จริงเอาไว้ แต่หมอดูข้างทางกลับรู้ถึงความลับของเธอได้ เธอทั้งคู่กำลังซ่อนความลับอะไรบางอย่างอยู่?"],"missfortune-color-story":["ร่วงหล่นท่ามกลางความตาย","ท่าเรือขาวของ Bilgewater ได้รับชื่อนี้เนื่องจากสิ่งปฏิกูลของนกที่ปกคลุมจากสุดข้างหนึ่งไปถึงอีกข้างหนึ่ง เป็นที่เดียวที่ให้ผู้ตายได้พักผ่อนอย่างสงบ ชาวเมืองนี้ไม่ฝังศพ พวกเขาส่งร่างกลับคืนสู่ทะเล สุสานของผู้ตายจมลึกอยู่ใต้น้ำลึกเย็นเยียบ ทำเครื่องหมายไว้ด้วยทุ่นป้ายสุสานหลายร้อยทุ่น บางทุ่นมีเพียงชื่อ ขณะที่อีกหลายทุ่นแกะสลักเป็นรูปที่คล้ายคราเคนหรือปีศาจทะเล"],"nami-first-steps":["ก้าวแรก","เธอมาพร้อมกับความใคร่รู้กับข้อความสุดน่ากลัว และพวกเขามาพร้อมกับคบเพลิงกับความหวาดกลัว"],"kayn-color-story":["The Blade of Millennia","Kayn ยืนผงาดในเงามืดแห่ง Noxtoraa รายล้อมไปด้วยศพของทหาร ใบหน้านั้นแต้มรอยยิ้มเย้ยหยัน ประตูชัย Dark Stone ตั้งตระหง่าน สดุดีความแข็งแกร่งแห่ง Noxus หล่อหลอมความกลัวและความจงรักภักดีให้แก่ประชาชนทุกคนที่เดินลอดผ่านมัน และสิ่งนี้คือศิลาแห่งสุสาน อนุสาวรีย์แห่งความมดเท็จและความจองหอง ทั้งยังเป็นสัญลักษณ์ของนักรบผู้สิ้นชีพที่บังอาจแข็งขืนในอำนาจ"],"urgot-color-story":["บุตรแห่ง Ur","พวกเรากำลังวิ่งผ่านถนนที่ความมืดมนปกคลุมทั่วไปหมด ไม่สามารถมองเห็นแม้แต่ท่อน้ำหรือแม้แต่เห็นตัวเองผ่านกระจก Zori คือสิ่งเดียวที่เหลืออยู่ รอยยิ้มของเธอคือความสวยงามเพียงอย่างเดียวภายใต้ความสกปรกทั้งมวล Blenk ผู้เต็มไปด้วยสีสันและความคิดยืนอยู่ข้างหลังเธอ Scuzz โผล่มาด้านหลัง เขาคือความสกปรกของ พวกเรา เขาคือทุกสิ่งที่ของคำนิยามว่าสกปรก เขาตะโกนชื่อกลุ่มของเราก้องไปทั่ว เขาทำให้ทุกที่เป็นที่ของเรา"],"graves-color-story":["นัดสุดท้าย","เขาหลบซ่อนตัวในบาร์ที่ว่างเปล่า เลือดไหลจากบาดแผลนับสิบจุด และถูกล้อมด้วยคนพร้อมอาวุธที่ต้องการสังหารเขา นับได้ว่า Malcolm Graves เคยพบเจอวันที่ดีกว่านี้ แต่เขาก็เคยพบเจอวันที่เลวร้ายกว่านี้ด้วย เขาจึงไม่กังวลอะไรนัก Graves พิงกับบาร์ที่พังพินาศ แล้วหยิบเครื่องดื่มมาหนึ่งขวดพลางถอนหายใจเมื่ออ่านฉลาก"],"gangplank-color-story":["โลหิตผสมน้ำ","กัปตันสงครามของ Noxus ร่างสูงใหญ่ยืนสั่นและปล่อยขวานหลุดมือเมื่อ Gangplank ดันดาบสั้นของเขาให้แทงลึกเข้าไปในลำตัวของชายผู้นั้น เลือดแตกฟองจากริมฝีปากของนักรบผู้นั้นในระหว่างที่เขากำลังพูดคำสบถที่ไร้เสียง"],"twistedfate-color-story":["เดิมพันอีกเท่าตัว","สายตาทุกคู่ใน Fortune's Glory จับจ้องไปยัง Twisted Fate เขารู้สึกว่าลูกค้าหลายรายของโรงพนันแห่งนี้มองเขาด้วยความอิจฉา ความตื่นเต้น และความชิงชัง ด้วยความหวังจะได้เห็นเขาสูญสิ้นทุกสิ่งในการเปิดไพ่ใบสุดท้าย"],"jhin-color-story":["ชายไม้เท้าเหล็ก","หนึ่ง"],"tales-of-ornn":["ตำนานอันสาปสูญของ Ornn","\"ข้าไม่เคยเห็นเทพเจ้าผู้ถูกลืม ยายของข้าเล่านิทานพวกนี้ให้ข้าฟังซ้ำแล้วซ้ำอีกเป็นพันๆ รอบ แต่ยายเองก็ไม่เคยเห็นเทพเจ้าผู้ถูกลืมนี่หรอกนะ แล้วยายของยาย หรือยายของยายของยายเองก็ไม่เคยเห็นเหมือนกัน ตำนานของเทพเจ้าผู้นี้เล่าขานกันเฉพาะยามที่อยู่ล้อมรอบกองไฟอันลุกโชนร่วมกันรับประทานปลาเผา ยิ่งเราไล่ย้อนเรื่องราวของบรรพบุรุษเรากลับไปไกลเท่าไร นิทานพวกนี้ก็ยิ่งดูมีเค้าว่าเป็นเรื่องจริงมากเท่านั้น\""],"ornn-color-story":["เสียงจากหัวใจ","ไม่รู้ว่ามีใครจุดไฟ แต่เราเห็นควันไฟห่างออกไป"],"star-guardian-starfall":["ดาวตก","ฉันมักฝันถึงความฝันนี้อยู่เสมอ ๆ"],"fizz-color-story":["เหรียญ Kraken นำโชค","อ้าว ว่าไงไอ้ตัวจ้อยทั้งหลาย ทำไมพวกเจ้ายังไม่ไปนอนอีกล่ะ? อะไรนะ? เจ้าอยากเรื่องเล่าก่อนนอนจากเฒ่า Lars ขาเดียวคนนี้รึ หือ?"],"mount-targon-story":["อ่านข้อมูลของหุบเขาเพิ่มเติม","Mount Targon คือยอดเขาที่สูงที่สุดใน Runeterra ภูเขาหินคุกรุ่นด้วยไอแดดตั้งตระหง่านท่ามกลางยอดเขามากมายที่ไม่เหมือนที่ใดในโลก Mount Targon ตั้งอยู่โดดเดี่ยว ห่างไกลจากอารยธรรม และเกือบเป็นไปไม่ได้ที่จะเดินทางไปถึงแม้จะเป็นผู้แสวงหาที่มุ่งมั่นที่สุด"],"zoe-color-story":["พบกับ Zoe","ในขณะที่กำลังคิดถึงร้านขนมเค้ก Zoe พุ่งออกไปในอากาศ ทิ้งตัวลงให้กับแรงโน้มถ่วง ขณะที่กำลังหล่น เธอยืนมือออกไปขณะที่รู้ตัว และสร้างทางเชื่อม ประตูมิติเปิดขึ้นด้านล่างของเธอและเชื่อมต่อกับอีกสถานที่หนึ่งในทันที เธอตกลงไปในประตูมิติ มวลสารของเธอถูกกระแทกไปมาและระเบิดออกขณะที่เธอท่องไประหว่างมิติ"],"project-of-rats-and-cats-and-neon-mice":["Of Rats and Cats and Neon Mice","The doctor stumbles on the slick bridge. His hand reaches out for the worn guardrail as his foot loses connection to the wiring in his ankle. For a moment, he is disoriented. His vision slips from the wet floor plates of the commuter overpass to the unending assembly of metal, glass, and perpetual light that is Upper Central."],"varus-color-story":["Dark Kin","Varus ลัดเลาะตามแม่น้ำที่ไหลผ่านทะเลทราย น้ำนั้นขุ่น แต่ดื่มได้ ร่างใหม่ที่ถูกสาปให้ถือครองธนูของเขานั้นสวยงาม รวดเร็วและแข็งแรง แต่ก็มาพร้อมกับความอ่อนแอของร่างเนื้อ มันทั้งหิว และกระหาย"],"trifarian-legion":["กาลครั้งหนึ่ง ผองเราคือราชันย์","ชื่อของข้าคือ Alyssa Roshka Gloriana val-Lokan เกือบสองพันปีที่บรรพบุรุษของข้าปกครอง Delverhold ในฐานะกษัตริย์"],"swain-color-story":["แผนการแห่งผงสีทมิฬ","เขามาถึงค่ายก่อนที่การประชุมแผนการรบจะเริ่มขึ้น ถูกขนาบข้างโดยกลุ่มทหารพิเศษ ซึ่งถูกเลือกมาจาก Trifrian Legion พวกทหารยืนอยู่ข้างหน้าทางเข้า ในขณะที่เขาก้าวเข้ามา"],"kaisa-color-story":["หญิงสาวที่กลับมา","“ฟังฉันดีๆนะ” ฉันบอกเด็กสาวที่บังเอิญมาเจอเข้า “ตั้งใจฟังนะ เหลือเวลาไม่มากแล้ว”"],"where-icathia-once-stood":["สถานที่ซึ่งเคยถูกเรียกว่า Icathia","ชื่อของข้าคือ Axamuk Var-Choi Kohari Icath’or"],"the-road-to-ruin-story":["","เมื่อครั้งข้ายังเยาว์วัย พี่ชายเคยถามข้าว่า: “เจ้าคิดว่า สายลมนั้นพัดไปในทิศทางใด มันกำลังหนี หรือเฝ้าตามใคร?”"],"a-sword-without-a-sheath-story":["","ดาบที่ไร้นาย จะมีค่าอันใดกัน? การจะปั้นนักดาบขึ้นมาสักคนนั้นเป็นเรื่องง่าย แต่การสอนเพื่อไม่ให้เขาฆ่าคน นั่นเป็นสิ่งที่ยากยิ่ง"],"irelia-color-story":["ชื่อที่แปดเปื้อน","“ข้าเคยเชื่อในตัวเจ้า Blade Dancer!” เขาสำลักเลือด “เจ้านำทางพวกเรา...”"],"confessions-of-a-broken-blade-act-1-story":["คำสารภาพของดาบที่แตกหัก: ตอนที่ 1","- I -"],"confessions-of-a-broken-blade-act-2-story":["คำสารภาพของดาบที่แตกหัก: ตอนที่ 2","Riven จะต้องเข้ารับการตัดสินเรื่องการฆาตกรรมอาจารย์ของ Yasuo หลักฐานใหม่ได้ถูกเปิดเผย มันคือเศษของดาบที่เเตกหัก"],"confessions-of-a-broken-blade-act-3-story":["คำสารภาพของดาบที่แตกหัก: ตอนที่ 3","เมื่อการตัดสินได้สิ้นสุดลงเเล้ว Riven ก็ต้องพบกับฝันร้ายในอดีตของเธอ"],"tahmkench-color-story":["ความโศกเศร้าของนักพนัน","โอ้โห เป็นกอบเป็นกำเลยนะ! ได้มาจากโต๊ะพนันสินะ? งั้นชนหน่อยเพื่อสุขภาพที่ดี เอ้า ชน"],"pyke-color-story":["จากนั้นก็... ฟัน","Mazier นอนเหยียดตัวอยู่บนแผ่นไม้ผุ ๆ คลื่นซัดเข้ามากระทบโขดหินเบื้องล่าง หัวใจที่ค่อยๆเต้นช้าลงเรื่อยๆกำลังสูบฉีดเลือดของเธอไหลลงไปในทะเล เธอจ้องมองขึ้นไปยังด้านบนผ่านบ้านเรือนที่ตั้งตระหง่านอยู่ไปจนถึงดวงดาวที่อยู่ห่างไกลออกไป"],"nautilus-color-story":["The Ophidian","ม่าย ไม่ ตรงนั้นยังว่างอยู่ ดึงเก้าอี้ออกมาและทิ้งตัวลงตรงนั้นซี๊ เพื่อน... หึหึ ว่ากันตามประสบการณ์ของข้านะ มันไม่ใช่คำที่ดีเท่าไหร่หร๊อก"],"aatrox-color-story":["กรงขัง","ความมืดมิด"],"the-legend-of-the-darkin":["ตำนานของเหล่า darkin","เหล่า Darkin ถูกสาปถึงสามครา—ครั้งแรกโดยศัตรูโบราณที่พวกเขาต่อกรด้วย และอีกครั้งโดยการล่มสลายของอาณาจักรอันแสนรุ่งเรืองของพวกเขา และครั้งสุดท้ายโดยการทรยศที่สาปส่งพวกเขาไปตลอดกาล"],"twilight-of-the-gods":["สนธยาของเหล่าทวยเทพ","พวกเขาเคลื่อนทัพเข้ามายังนครอันไร้ชีวิตที่อยู่ใต้ร่มเงาของหุบเขาในยามราตรี กองทหารนับพัน แต่ละกองทัพล้วนมีสัญลักษณ์แห่งโลหิตของเหล่า Sunborn ที่บ่งบอกถึงชาติตระกูลของ Ascended ซึ่งเป็นผู้นำของแต่ละกองทัพนั้น"],"the-dreaming-pool":["บ่อนิมิต","ป่าที่ค่อย ๆ มืดลงแห่งนั้นเต็มไปด้วยสิ่งสวยงาม แต่เด็กสาวไม่แม้แต่จะชายตามองสิ่งใด ในขณะที่เธอย่ำผ่านทางป่าที่มีลมโกรก"],"from-the-ashes":["จากเถ้าธุลี","“ข้าทำไม่ได้”"],"akali-color-story":["","“อ๊ะ—เฮ้! โบลี่” ข้าตะโกน “สักข้าแรงไปหน่อยนะ เจ้าว่าไหม?”"],"the-eye-in-the-abyss":["ดวงเนตรแห่งห้วงอนธการ","ซิกวาร์ ศรครึ่งแล่ง ได้ย่อตัวคุกเข่า โค้งศีรษะลง ในขณะที่สายลมภายนอกประตูใหญ่โหยหวนราวกับภูตเหมันต์ในตำนาน"],"nunu-color-story":["ศิลายะเยือก","ข้าสะดุ้งตื่นขึ้นฉับพลัน เช่นเดียวกับเรื่องราวที่เริ่มเล่าเมื่อกลางคัน"],"frozen-hearts":["ดวงใจเยือกแข็ง","“ท่านแม่... ข้าถามอะไรหน่อยได้มั้ย?”"],"the-man-with-the-grinning-shadow":["บุรุษผู้มาพร้อมรอยยิ้มแห่งเงามืด","“แกคือนายอำเภอใช่ไหม?”เจ้ามนุษย์หนองน้ำเอ่ยขึ้น ร่างของมันปกคลุมไปคราบขมุกขมัวของฝุ่นดินจากที่ราบลุ่มและหนามแห้ง ๆ ของต้นกระบองเพชรที่ถูกโปะเอาไว้ด้วยโคลนจากก้นบึ้งอันเก่าแก่ของหนองน้ำ มันยืนอยู่หน้าทางเข้าห้องพักส่วนตัวบนรถไฟของลูเซี่ยน ร่างดูนั้นทั้งเล็กและใหญ่โตในเวลาเดียวกัน มันสวมเสื้อผ้าขาด ๆ ที่เก็บมาจากพวกนักร่อนทองที่ตายในเขตรอบนอกของโพรเกรส"],"the-lure":["ล่อลวง","ทุกครั้งเวลาคีโลจะจู่โจม เขาจะร้องออกมาว่า “เซอร์ไพรซ์!” ก่อนเสมอ"],"an-explorers-journey":["ภาคสนามของนักสำรวจ","บันทึกลายมือเกี่ยวกับการค้นพบห้องสมบัติศักดิ์สิทธิ์อันรุ่งโรจน์"],"kassadin-color-story":["ทะเลทรายรู้จักผู้ใด?","ชูริม่ากำลังจะล่มสลาย และข้าไม่คิดว่านางจะฟื้นกลับคืนมาอีก"],"lucian-color-story":["ผู้ล่าเงามืด","พวกมันพุ่งเข้ามาหาลูเซี่ยนด้วยร่างเงาที่ไร้รูปทรง กางกรงเล็บอันไร้สสารและดาบโบราณขึ้นสนิม พวกมันเคลื่อนไหวรวดเร็ว...แต่เขาเร็วกว่า"],"the-curators-gambit":["เล่ห์ลวงแห่งนักคัดสรร","โอเค แค่อยากจะให้มันเคลียร์น่ะนะ—ฉันไม่ได้ต้องการยุ่งอะไรกับ “จอมมาร” หรืออะไรก็ตามที่จานุ๊คกำลังพูดถึงเลย ฉันแค่พยายามจะขายขวดยางี่เง่าให้กับคนที่จ้างให้ฉันไปหามันมาให้ก็เท่านั้นเอง มันน่าจะเป็นเรื่องง่ายๆ"],"art-is-life":["ชีวิตสั้น ศิลปะยืนยาว","ค่ำคืนในน็อกซัสไม่เคยเงียบสนิท"],"nocturne-color-story":["ประตูเงา","“ขออีกเรื่องนะครับพ่อ”"],"veigar-color-story":["เรื่องราวที่แท้จริงอันแสนสะพรึงกลัวของปิศาจร้ายแห่งหอคอยโบลแฮม","เมฆครึ้มสีดำมืดเคลื่อนออกจากภูเขาอาร์เจนท์ มันเป็นการข่มขู่ที่ดี แต่ดูเหมือนจะไม่ได้ผลอะไร"],"popstars-lyrics":["POP/STARS","Intro"],"popstar-interview":["บทสัมภาษณ์: ล้วงลึก K/DA","PopRox: สวัสดีครับผู้ฟังทั่วโลกทุกท่าน! วันนี้พวกเรามีแขกรับเชิญที่เรียกได้ว่าพิเศษสุด ๆ มาเยี่ยมด้วย และตอนนี้ผมก็กำลังอยู่กับสี่สาว K/DA แล้ว ถ้าคุณไม่เคยได้ยินชื่อของพวกเธอ ซึ่งถามจริง ทำไมคุณถึงจะไม่เคยได้ยินเรื่องของพวกเธอกันล่ะ นี่ไปอยู่ในถ้ำที่ไหนมารึไง?! รีบตรงดิ่งไปที่ TouTube แล้วเซิร์ชหาเพลงฮิตของพวกเธอ “POP/STARS” เดี๋ยวนี้เลยนะ"],"pajama-party":["คำเชิญแห่งปาร์ตี้ค้างคืน","โอเค ฉันก็ต้องยอมรับล่ะนะว่าการที่ไปกระแทกประตูใส่หน้าพวกนั้นนี่มันก็ออกจะเกินกว่าเหตุไปหน่อย"],"at-the-edge-of-the-world":["ณ สุดขอบโลก","“เจ็ดครั้ง” อิซาร์ด ทอมมิริ กล่าว พยายามลดเสียงและการแสดงออกทางใบหน้าให้ปกติที่สุด"],"nidalee-color-story":["เลือดมนุษย์","เสียงเปรี้ยงลั่นดังสนั่น กลิ่นของน้ำมัน ควันไฟ และผงดินปืน"],"neeko-color-story":["ปีศาจแห่งป้อมคัลดูการ์","“เจ้ากำลังจะบอกว่ามีผู้บุกรุกเรอะ?” ตาของชายอ้วนโตขึ้น"],"soraka-color-story":["ครึ่งทางระหว่างดวงดาวและผืนดิน","มันเป็นค่ำคืนที่เหมาะเจาะสำหรับการดื่มชาซักแก้ว แน่ล่ะ อากาศหนาวเย็น แต่โปร่ง—จริงๆแล้ว เป็นค่ำคืนที่แจ่มใสที่สุดเท่าที่หุบเขาทากอนจะมีได้เลย โซรากะกำลังรอให้แขกของเธอมาถึง หิมะในหม้อหินเริ่มละลายบนเปลวไฟของเตาผิงกลางกระโจมหลังน้อยของเธอ และเมื่อมันเริ่มร้อนขึ้น ทั้งกระโจมก็เต็มไปด้วยกลิ่นหอมของใบไม้แห้งและสมุนไพรบนภูเขา"],"demacian-heart":["หัวใจแห่งเดมาเซีย","เด็กชายรู้สึกชื่นชมดอกดอร์มิสท์รูทสีเหลืองที่เติบโตแทรกผ่านชั้นดินเยือกแข็งขึ้นมาได้ มันเป็นหนึ่งในพี่น้องอีกนับร้อยที่งอกงามอยู่ในพื้นที่เล็ก ๆ ที่เปี่ยมสีสันท่ามกลางดินแดนแห้งแล้งหม่นสี เขาคุกเข่าลงพินิจกลีบใบที่เบ่งบานแล้วสูดลมหายใจลึก สัมผัสสดชื่นของยามเช้ากับกลิ่นหอมของดอกไม้กล่าวคำทักทายแก่โสตนาสิก เด็กชายจึงเอื้อมมือออกไปหมายจะเด็ดเจ้าดอกไม้ขึ้นมา"],"trial-of-the-masks":["บททดสอบแห่งหน้ากาก","ลองจินตนาการว่าโลกใบนี้เปรียบเสมือนกระจกเงาดูสิ"],"ashe-color-story":["เส้นทางที่ยากลำบาก","กองไฟขนาดมหึมาได้ส่องสว่างขึ้นราวกับมีชีวิต เปลวเพลิงลุกโชติช่วงขึ้นสูงในอากาศ ในอดีตกาลที่ผ่านมา ชนเผ่าทั้งหลายล้วนถือว่าสิ่งนี้คือสัญลักษณ์แห่งการเริ่มต้นของงานเทศกาล"],"snow-day":["Snow Day","Snow falls all morning, blanketing the earth in fresh coats of white. One by one, feathery flakes trickle from the sky, gently at first, and then rapidly in unison. Soon, the howling blizzard muffles all sounds save for a peculiar racket coming from a nearby cave, where a shock of orange and blue bounces up and down, left to right."],"sylas-color-story":["เด็กใหม่","ดวงอาทิตย์ลอยขึ้นสู่จุดสูงสุดแล้ว มันอยู่สูงพอที่จะสาดแสงลงมายังค่ายของผู้ถูกเนรเทศที่ซ่อนตัวอยู่ลึกลงไปในหุบเขา จากเงื้อมเงาของเพิงพัก ไซลาสแห่งเดร็กบอร์นกำลังรอคอยหน่วยสอดแนมของเขาอยู่ด้วยความอดทน และในที่สุด เขาก็ได้เห็นเธอกำลังลัดเลี้ยวรอบเสาหินสูงที่อยู่ตรงบริเวณปากช่องผาเข้ามา พร้อมกับพาเอาเจ้าเด็กแปลกหน้าตาโตคนหนึ่งมาที่ค่ายด้วย"],"turmoil":["ระส่ำ","“นึกยังไงถึงส่งพวกเราออกมาไกลถึงนี่กันนะ?” ทหารที่กำลังยืนกอดอกพิงผนังของเรือนกำแพงเอ่ยขึ้น “ถนนของมหานครมีเลือดนองเต็มไปหมด แต่พวกเราดันถูกส่งมาที่ชายแดนงั้นเหรอ?”"],"masteryi-color-story":["การกลับบ้าน","ใบไม้เหี่ยวแห้งร่วงลงจากกิ่งไม้ที่สั่นไหว เมื่อสายลมพัดผ่านไปทั่วเนินของหุบเขา ยีลอยตัวอยู่เหนือพื้นไม่กี่นิ้ว ดวงตาปิด มือประสานกัน ฟังเสียงเพลงยามเช้าที่ขับขานโดยเหล่านกบาฮิล กระแสลมเย็นสัมผัสใบหน้าและลูบผ่านคิ้วของเขา"],"annie-color-story":["ตัวปัญหา","ถ้ามีบางสิ่งที่มาร์ซินเชี่ยวชาญ นั่นคือการหลีกเลี่ยงปัญหา"],"katarina-color-story":["สาสน์บนปลายมีด","เสียงสะท้อนของฝีเท้า พื้นหินที่เย็นเฉียบ"],"silence-for-the-damned":["Silence for the Damned","Across the frozen river, the distant, glowing lights promised warmth and food. Udyr imagined a hearth fire crackling inside one of the city’s homes. Around the fire, bedding furs rested, prickling with warmth."],"kayle-color-story":["ด้วยเปลวเพลิงแห่งความเที่ยงธรรม","ช่องท้องของอาบริสขมวดแน่นเป็นเกลียวเมื่อเขาหยุดรั้งรออยู่บนขั้นบันไดของวิหารที่เรืองรองนั่น ที่ยืนตระหง่านเฝ้าพิทักษ์อยู่เบื้องหน้าประตูวิหารคือรูปสลักของท่านผู้พิทักษ์ แสงอาทิตย์อัสดงค์ทาบเงาลงบนใบหน้าหินสลัก ฉาบรัศมีเรืองรองอยู่รอบศีรษะที่กำลังน้อมต่ำลงมา รูปปั้นนั้นถูกสลักขึ้นมาด้วยศิลาสีขาวที่เปล่งประกายด้วยจุดกระจายสีทองคำแวววาว ปีกคู่ใหญ่ห่อหุ้มอยู่เหนือไหล่ขณะที่มือถือดาบสองเล่มทาบไว้กับอก สีหน้าภายใต้หมวกเกราะของรูปปั้นนั้นไร้ซึ่งอารมณ์อันใด เคร่งขรึมและสมบูรณ์แบบเกินกว่ามนุษย์หน้าไหนจะเทียบเคียง เทียนนับร้อยเล่มปกคลุมอยู่ทั่วทั้งฐานที่ปลายเท้าของรูปสลัก"],"canticleofthewingedsisters":["เพลงสวดแห่งสองพี่น้องผู้ครองปีก","ลำนำมหากาพย์ซึ่งสาบสูญไปแสนนานแล้วแห่งหอสมุดตระกูลคราวน์การ์ด, ไฮซิลเวอร์แมร์"],"morgana-color-story":["คำภาวนาแด่เทวาลัยอันแตกสลาย","รินสะดุดปลายเท้าเข้ากับรากไม้พลางเซถลาจวนจะล้ม เขาคว้าตัวเองเอาไว้ได้ก่อนจะเสียการทรงตัวไป ที่สองสามก้าวเบื้องหน้าของเขา ท่านป้ากำลังจ้องมองกลับมา"],"whatoncesailedfree":["สิ่งที่ครั้งหนึ่งเคยล่องไปด้วยเสรี","นักโทษยืนตระหง่านอยู่ตรงนั้น ข้อเท้าถูกล่ามตรวนเอาไว้กับเสาไม้ ข้อมือพันธนาการไว้ด้วยเชือกเส้นหยาบ โลหิตหยดรินจากแก้มลงมาสู่เสื้อตัวยาวสีดำติดตราสัญลักษณ์น็อกซัสของเขา ทิ้งรอยจุดสีแดงเป็นดวงบนนิ้วเท้าเปลือยเปล่า สูงขึ้นไปเหนือชายหนุ่ม ท้องฟ้ากำลังถูกทาบทาไปด้วยสีเทา บิดเบือนสีสันที่แท้จริงของมันไปจากสายตา"],"zyra-color-story":["ด้วยบุปผชาติ","ความชื้นเหนอะหนะของตลาดทอนนิก้าและกลิ่นกายอับ ๆ ของฝูงชนมักจะเร่งเร้าให้ผู้มาจับจ่ายต้องตัดสินใจอย่างรีบร้อนเสมอ แต่ฮาทิลลีกลับยืนนิ่งอยู่ตรงนั้น ดวงตาของเธอคล้อยจับอยู่ที่ดอกตูมหน้าตาแปลกประหลาดยุ่งเหยิงซึ่งห่อหุ้มด้วยกลีบใบสีแดงแห้ง ๆ นั่น รูปแบบตัวอย่างที่เธอไม่เคยเห็นที่ไหนมาก่อน"],"the-echoes-left-behind":["เสียงสะท้อนซึ่งถูกทอดทิ้ง","โลหิตก่อตัวเป็นวงเบื้องล่างเขา สีแดงเจิดจ้าสำแดงตนตัดผ่านศิลาสีขาวบริสุทธิ์ ดาบของเขาวางอยู่ใกล้ ๆ ใบดาบนั้นแตกหัก เหล่าเพชฌฆาตยืนอยู่รายล้อม เป็นเงาวูบไหวอยู่รอบวง แต่เขามองไม่เห็นสิ่งอื่นใดนอกจากเธอ"],"darius-color-story":["ถนนแห่งวินเทอร์สไปค์","เมื่อสนธยามาถึง รองเท้าบูทของมายาก็เปียกโชกไปด้วยหิมะหมดแล้ว แต่ละย่างก้าวล้วนเต็มไปด้วยสัมผัสของน้ำเย็นเฉียบเป็นเมือกเหนียวเหนอะตั้งแต่ส้นไปจนถึงปลายเท้า ราวกับมีมีดแล่เนื้อกำลังลากไปมาตามผิวเของเธออยู่"],"yuumi-color-story":["ผจญปลายักษ์","นอร์ร่าซึ่งเป็นยอร์เดิลของข้านอนหลับกรนใส่หน้าแผ่นกระดาษของเจ้าตำราซึ่งเป็นสหายของข้า หางของข้าส่ายสะบัดไปมาในขณะที่ฝูงผีเสื้อกลางคืนพากันบินเข้ามาผ่านหน้าต่างที่เปิดไว้ราวกับกลุ่มโคมลอย ข้าดีดตัวกระโดดด้วยความเริงร่าคีกคักและไม่ได้สนใจนักหรอกว่าจะจับพวกมันได้รึเปล่า ข้าดีดตัวให้ลอยสูงขึ้นไปเรื่อยๆ และตะปบพวกผีเสื้อกลางคืนที่บินว่อนอยู่รอบตัวข้า"],"the-whispering-doodad":["เสียงกระซิบจุกจิก","ข้าจะเล่าเรื่องทุ่งหญ้าของข้าให้เจ้าฟัง"],"leblanc-color-story":["หนามแห่งกุหลาบดำ","\"ข้าไม่เข้าใจเลย\" แม่ทัพแกรนธ์พึมพำในขณะที่พยายามป้องเปลวไฟตะเกียงของเขาไม่ให้ดับ \"ที่นี่ไม่มีอะไรเลย นี่มันทางตัน\""],"tryndamere-color-story":["ถ่านที่คุกรุ่น","ในแดนเหนือห่างไกลเช่นนี้ ค่ำคืนช่างมืดมิด ในห้องโถงชุมนุมของแอชและเจ้าบ่าวร่วมเลือดสาบานของนางมีเงามากมายทอดยาว กองไฟเริ่มหรี่ลงกลายเป็นเพียงกองถ่านระอุ ถ่านเหล่านี้อาจดูเหมือนมอดดับสนิท แต่ว่าแม้กระทั่งคนโง่ก็ยังรู้ดีว่าไม่ควรจับมันด้วยมือเปล่า แม้กระทั่งคนโง่ก็ยังรู้"],"mordekaiser-color-story":["การครองบัลลังก์ครั้งสุดท้าย","กำปั้นที่ชูเหยียด พลังแห่งศาสตร์มืดที่ก้าวขึ้นครอบงำ เบื้องหน้าเขาคือยอดสุดท้ายของหอคอยสุดท้าย ควันสีเข้มดั่งน้ำหมึกรวมตัวประสานกันเป็นแผ่นเหล็กสีดำ มอร์เดไคเซอร์จ้องมองดินแดนใต้อำนาจมืดของเขาด้วยความภาคภูมิใจ"],"qiyana-color-story":["ผู้ปกครองที่คู่ควร","\"เหงื่อข้าเริ่มไหลแล้ว บายัล ช่วยหาทางทำให้เหงื่อข้าหยุดออกมาทีเถอะ\""],"malphite-color-story":["รากเหง้าของต้นไม้พิษ","ฝุ่นลอยคลุ้งหนาดังผืนม่านในขณะที่ชูไรเดินตามหลังฮิวเล็ตต์ หัวหน้าผู้คุมอุโมงค์เหมืองผู้มีแขนขาจักรกล เดินลึกเข้าไปในปล่องเหมือง ชูไรหายใจผ่านเครื่องกรองอากาศและพยายามห้ามตัวเองไม่ให้จินตนาการว่าตลอดหลายปีที่ผ่านมามีนักขุดเหมืองชาวซอนมากมายเพียงใดที่เคยหายใจผ่านอุปกรณ์นี้ เปลวไฟจากพลุไฟเคมีที่ห้อยอยู่บนขื่อเพดานไม้หยดลงใส่หมวกเหล็กนิรภัยที่มีรอยกัดกร่อนซึ่งพวกเขาสวมอยู่ระหว่างที่เดินผ่านไป"],"pantheon-color-story":["แด่ผู้ลาลับ","ตอนที่ข้าลงมาถึงซากปรักหักพังแห่งเนรีเมเซธ ไม่ได้รู้สึกเหมือนเหินเวหาลงมาด้วยพลังศักดิ์สิทธิ์แห่งสวรรค์เลย แต่เหมือนกับร่วงหล่นลงมามากกว่า"],"khazix-color-story":["การปรับเปลี่ยน","การถูกเนรเทศเท่ากับการถูกลบตัวตน"],"the-twilight-star":["ดาวสนธยา","ฉันมีคำถามที่อยากถามเธอเยอะแยะไปหมด ฉันแอบเหล่มองเธอระหว่างที่เราเดินไปด้วยกัน เธอมองตรงไปข้างหน้า ฉันเห็นเธอกวาดสายตามองไปทั่วยังสุดขอบอาณาเขตของสวนสาธารณะซึ่งอยู่ไกลออกไป ผมสีแดงของเธอสะท้อนประกายแสงแดดสุดท้ายของยามบ่ายในทุกก้าวที่เดิน เธอเห็นอะไรรึเปล่านะ? ปกติแล้วเธอลาดตระเวนแบบนี้เหรอ? เธอเบื่อรึเปล่านะ? เธอมาที่นี่ทำไม? ไม่อยากเชื่อเลยว่าเธอจะอยากมา เธอมาทำไมนะ? ฉันเร่งฝีเท้าเพื่อตามเธอให้ทัน"],"homebound":["คืนสู่เหย้า","ลูเซี่ยนนั่งอยู่บนยอดเนินเขาใต้เงาของต้นไทรใหญ่และกวาดสายตามองไปทั่วหุบเขาเบื้องล่าง มือเขาวางอยู่บนปืนสั้นทั้งสองกระบอกของเขา นิ้วก็ลูบแตะผิวโลหะสัมฤทธิ์ หมอกทมิฬโรยตัวปกคลุมพื้นที่ราบลุ่มสีเขียวชอุ่มและกลืนกินทุกสิ่งที่มันเคลื่อนผ่าน แฮร์โรว์วิงได้เริ่มต้นขึ้นบนเกาะแห่งนี้ตั้งแต่เมื่อหลายชั่วโมงที่ผ่านมา"],"with-hell-before-them":["แดนอเวจีเบื้องหน้า","7 มิถุนายน 1868"],"spear-of-targon":["The Spear of Targon","A lone figure awaited the armed convoy, standing silhouetted against the sun. His heavy cloak and the long plume atop his helm billowed in the hot, dry desert wind. A tall spear was held at his side."],"senna-color-story":["เสียงของผู้วายชนม์","บนเกาะของข้ามีคำกล่าวว่า \"สายลมสามารถพูดได้ต่อเมื่อมันขโมยลมหายใจของเราเท่านั้น\" เจ้าอยากให้ข้าเล่าเกี่ยวกับหมอกทมิฬที่มาทักทายข้าในตอนที่ข้าเดินทางมาถึงหมู่บ้านชาวไอโอเนียเป็นครั้งแรกโดยสวมหมวกฮู้ดไว้และสะพายปืนใหญ่โบราณไว้ที่หลังอย่างนั้นเหรอ?\""],"shackles-of-belief":["ตรวนแห่งศรัทธา","ธอร์วา ภคินีแห่งน้ำแข็ง ดึงสายบังเหียนให้ดรูวาสก์ร่างยักษ์ของนางหยุดตรงข้างวรินน่า สการ์มาเธอร์แห่งเผ่าวินเทอร์คลอว์ เจ้าสัตว์ขนฟูรุงรังส่งเสียงฟืดฟาดประท้วง มันพ่นลมหายใจร้อนที่แลเห็นเป็นไอเมื่อกระทบอากาศภายนอก"],"karma-color-story":["ตราไว้ในดวงจิต","วาทัยหมุนแหวนหยกบนนิ้วด้วยความรู้สึกกระวนกระวายใจในขณะที่เงยหน้าจ้องอารามซึ่งฝังตัวอยู่ตรงไหล่เขา แท่นบูชาไร้สิ้นสุด ซึ่งเป็นบ้านของคาร์มา ตลอดเวลาที่ผ่านมา นางไม่คิดเลยว่าจะได้กลับมาที่นี่อีกครั้ง การเดินทางเต็มไปด้วยความเจ็บปวดมากมาย โดยเฉพาะอย่างยิ่งจากเข่าที่มีปัญหาของนาง วาทัยสูดลมหายใจลึกและออกเดินขึ้นไปตามทาง มุ่งหน้าสู่วิหารขนาดเล็กซึ่งตั้งอยู่ตรงทางเข้าห้องสมาธิส่วนตัวของคาร์มา"],"aphelios-color-story":["เจ้าคือศัตราวุธ","เขาเริ่มต้นการฝึกโดยสูดลมหายใจหนึ่งครั้ง เข้าและออก"],"child-of-zaun":["บุตรแห่งซอน","อะไรคือความแตกต่างระหว่างกฎหมายกับความสงบเรียบร้อย?"],"sett-color-story":["หายนะแห่งความโลภ","\"ใครเฝ้าโต๊ะเก็บเงิน?\" ข้าถาม"],"dream-thief":["โจรความฝัน","แม่มดน้ำแข็งไม่ได้หลับใหลอยู่ในป้อมปราการของนาง นางเข้าสู่ห้วงนิทราได้ไม่ว่าจะอยู่แห่งหนใด ได้ในทุกแห่งหน และได้แม้จะไม่ได้อยู่ในแห่งหนใดเลย บางครั้งก็พร้อมกันทั้งหมดนี้ด้วย"],"bow-and-kunai":["คันธนูและคุไน","อากาศของดินแดนชอน-ซานทางตอนใต้อบอวลไปด้วยเวทมนตร์อันบริสุทธิ์ไร้การปรุงแต่ง พลังอันลึกลับไหลปกคลุมทั่วทั้งดินแดน ทะลวงผ่านแมกไม้ที่แผ่ใบสารพัดสีแทงยอดขึ้นสู่ผืนฟ้า ทั้งบานเย็น น้ำเงินคราม ฟ้ากระจ่างและเหลืองอำพัน คลี่แผ่ราวกับพัดในมือของผู้ร่ายรำ"],"name-of-the-blade":["นามของคมมีด","ในอากาศมีกลิ่นทองแดงผสมอยู่"],"destiny-and-fate":["โชคชะตาฟ้าลิขิต","อ้า บิลจ์วอเทอร์"],"axiomata":["สัจพจน์","แม่น้ำสายนี้นำพาความทรงจำมาจากโลกที่ตายไปแล้ว ข้าสงสัยว่ามีเพียงข้าคนเดียวหรือเปล่าที่สามารถหาความทรงจำเหล่านั้นพบ"],"ambitions-embrace":["โอบกอดแรงปรารถนา","ถูกพันธนาการไว้ด้วยความมืด"],"perennial":["นิรันดร์กาล","หลายๆ คนพากันหวั่นใจว่าวิญญาณจะไม่มีวันกลับมาผลิบานที่ไอโอเนียอีกต่อไปแล้ว และนี่คือสัญญาณที่บอกว่าความไม่สมดุลยังคงระรานดินแดนแห่งนี้และชาวไอโอเนียอยู่ คนรุ่นนี้มีจำนวนมากที่เติบโตเป็นผู้ใหญ่โดยที่ไม่เคยพบเห็นวิญญาณผลิบานหรือเทศกาลวิญญาณผลิบานเลยแม้สักครั้ง"],"out-of-time":["ต่อเวลา","การไล่ล่า"],"sisterhood-of-war-i":["คณะสตรีแห่งสงคราม ตอนที่ 1: แผลเก่า","\"ที่ฟังไปมีอะไรที่เจ้าเข้าใจไม่ชัดเจนหรือเปล่า?\""],"volibear-color-story":["ผู้เรียกพายุ","\"วัลฮีร์!\""],"kaisa-monstrous-story":["อสุรกาย","ใต้ผืนพิภพนั้นมีแสงสว่างให้เห็น หากเจ้ารู้ว่าต้องมองหาจากที่ใด"],"legend-of-the-frozen-watchers":["ตำนานแห่งวอทเชอร์ใต้ผืนน้ำแข็ง","ในบรรดาเรื่องเล่าของเฟรย์ลยอร์ดยุคโบราณที่ยังคงอยู่ยืนยาวมาถึงสมัยใหม่นั้น มีเรื่องหนึ่งและเพียงเรื่องเดียวเท่านั้นที่ทำให้แม้แต่ไอซ์บอร์นที่หาญระห่ำที่สุดก็ยังต้องสั่นสะท้านด้วยความหวาดกลัว"],"rumble-color-story":["เศษขยะแดนชูริม่า","ตอนนั้นข้ากำลังเดินไปตามลานตลาดเล็กๆ แห่งนี้ซึ่งอยู่ห่างออกมาจากย่านหอสมุดของนาชราเม ที่นี่มีแต่ฝุ่นเต็มไปหมดและปูด้วยพื้นหินที่เก่าแก่กว่าจักรวรรดิหลายแห่ง ปกติแล้วที่นี่จะค่อนข้างเงียบทีเดียว ข้ากำลังอารมณ์ดีหลังจากที่เพิ่งต่อรองกับพวกพ่อค้ามนุษย์ซื่อบื้อในตลาดใหญ่ได้สำเร็จ ข้าพูดทำนองว่า \"เจ้าจะเอาเท่าไรสำหรับกาน้ำชานั่น?!\" แล้วก็ \"ไม่มีทางที่นี่จะเป็นคทายุคเทพจุติของแท้หรอก ตกแต่งลวดลายแบบนั้นน่ะ!\""],"feast-fit-for-a-king":["มื้อราชา","ร่างใหญ่เทอะทะย่ำลุยหิมะที่สูงถึงระดับเอวของหุบเขาแห่งนี้ เขาไต่ขึ้นเนินชันของภูเขาอย่างยากเย็นทว่าเต็มเปี่ยมไปด้วยความมุ่งมั่นที่ท้าทายพายุหิมะให้หยุดยั้งเขาดู เส้นทางด้านหลังที่เขาย่ำผ่านนั้นแลเห็นเป็นคูร่อง กรงเล็บของเท้าคู่หนักครูดจิกผิวน้ำแข็งใต้กองหิมะเป็นสะเก็ดในทุกก้าวที่เดินไป สายลมโหมกระหน่ำพัดเสื้อคลุมของเขาที่ใช้ชิ้นหนังสัตว์มาเย็บปะต่อกันให้ปลิวสะบัด เขาดึงเสื้อคลุมให้กระชับกายยิ่งขึ้น"],"riven-color-story":["รอยแตกร้าวและรอยแผลเป็น","\"เจ้ามาที่ไอโอเนียได้อย่างไรรึ สหาย?\""],"yasuo-color-story":["พี่ชายและน้องชาย","เสียงร้องไห้นั้นดังมาจากเด็กผู้ชายคนหนึ่ง อายุราวหกขวบ หรืออาจจะสักเจ็ดขวบได้"],"sisterhood-of-war-ii":["คณะสตรีแห่งสงคราม ตอนที่ 2: วิญญาณอาฆาต","นางหายใจไม่ออก"],"piece-of-shadow-cake":["ดั่งพลิกเงาฝ่ามือ","ซายาห์กระโดดขึ้นไปอยู่กลางดงพุ่มใบของต้นไม้และหลบกระสุนปืนที่ถล่มยิงมาจากฝั่งกำแพงวิหาร พวกมนุษย์เรียกอาวุธของพวกเขาว่า \"ไรเฟิลคาชูริ\" มันเป็นอาวุธที่มีพลังพิฆาตถึงตายและเห็นได้ชัดว่าทหารรักษาการณ์ของเมืองนี้เป็นนักรบที่ผ่านการฝึกฝนมา แต่พวกเขาลงมือช้าเกินไป ช้าเกินกว่าจะโจมตีนางได้ ช้าเกินว่าจะหยุดยั้งชาวเผ่าที่อยู่ใต้บัญชาการของนางได้ เพราะตอนนี้พวกชาวเผ่าปีนขึ้นไปบนวิหารโบราณจนถึงสิ่งที่อยู่ภายใต้การอารักขาของวิหารนั้นเรียบร้อยแล้ว... ควินลอน"],"lillia-color-story":["สวนแห่งความฝัน","เด็กคนนั้นค่อยๆ เดินช้าๆ เข้ามาในผืนป่า และบางครั้งก็เดินอยู่ใต้ผืนป่าในจุดที่แผงใบไม้แผ่เรียงถักทอต่อกันดั่งผ้าห่มสีเขียวผืนยาวตัดกับหมู่เมฆเบื้องบน โอ้! และบางครั้งก็เดินอยู่เหนือผืนป่าในจุดที่รากแผ่ชอนไช! อย่าสะดุดล้มนะ แม่หนูน้อย อย่าสะดุดล้ม และตอนนี้…นางก็กำลังเดินผ่านมัน"],"dead-in-the-water":["สุสานกลางน้ำ","สายน้ำแดงฉาน ซัดโถมเข้าออก"],"sisterhood-of-war-iii":["ซึ่งมิอาจประสาน","แสงจวนเจียนจะลาลับ"],"yone-color-story":["สะบั้น","เด็กชายคนนั้นวิ่งเร็วสุดฝีเท้าด้วยความหวาดหวั่นพรั่นพรึง"],"shield-of-remembrance":["โล่เกียรติภูมิรำลึก","ควินน์วิ่งฝ่าไปในป่าแห่งนั้นด้วยฝีเท้าที่แผ่วเบาว่องไว ตอนนี้เลยรุ่งสางมาแล้ว แต่ว่าดวงอาทิตย์ยังลอยไม่พ้นแนวยอดเขาฟากตะวันออก แสงแดดสีซีดไร้ไออุ่นทาบทาทุกสิ่งเป็นสีเทาเข้มอ่อนหลากระดับไล่กันไป ลมหายใจที่ผ่อนออกมาเป็นจังหวะสม่ำเสมอของควินน์แลเห็นเป็นไอควัน"],"sona-color-story":["การแสดงครั้งสุดท้าย","กลิ่นเก่าๆ ที่คุ้นเคยพุ่งเข้าสู่ประสาทสัมผัสของนางเป็นอย่างแรก ฟาง สตรอว์เบอร์รีและ ไม้เนื้อแข็ง ลานของโรงแรมอาร์เจนไทน์ อินน์มีกลิ่นเฉพาะตัวอันเป็นเอกลักษณ์ที่ฉุดความทรงจำอันเจ็บปวดในอดีตแสนยาวนานให้ผุดขึ้นมา การแสดงดนตรีนับร้อยครั้ง ใบหน้านับพันที่มีแสงสว่างจากโคมไฟฉายส่อง และที่เจ็บปวดที่สุดก็คือ ช่วงเวลาที่สิ่งต่างๆ ในเดมาเซียนั้นเรียบง่ายและสุขสันต์กว่านี้"],"poetry-with-a-blade":["บทกวีแห่งคมดาบ","ยีทำหน้านิ่วคิ้วขมวดใส่อาจารย์ดอแรนในขณะที่ชายอาวุโสลากสังขารปีนขึ้นมาหาเขา อย่างกับปูทะเลในฤดูผสมพันธุ์ เป็นความคิดที่ไม่ค่อยจะให้เกียรติ แต่ด้วยอายุของปรมาจารย์ช่างฝีมือแล้ว นี่ถือเป็นคำชม"],"samira-color-story":["ใจกล้าท้ามฤตยู","ร้านอาวุธแห่งนั้นดูเขลอะ เป็นแบบที่ซามิร่าชอบเป๊ะ ป้ายแขวนเอียงกระเท่เร่อยู่ตรงประตู ร้านอาวุธลานิ & มิเอล ซามิร่าได้ยินเกี่ยวกับร้านเล็กๆ ในน็อกซัสแห่งนี้จากกัปตันอินดาริซึ่งได้ข้อมูลจากหนึ่งในเครือข่ายนักก่อวินาศกรรมของนาง เรื่องนั้นบวกกับข้อเท็จจริงที่ว่าพวกเด็กฝึกงานทำงานพิเศษเป็นช่างสักด้วยก็เพียงพอแล้วที่จะทำให้ซามิร่าสนใจขึ้นมา นางก้าวเข้าไปโดยมีอินดาริตามหลัง"],"courting-disaster":["ความรักชักนำพินาศ","จากประมวลจดหมายของลอร์ดเอเม็ตแห่งตระกูลซัสเซนถึงเลดี้เอลิส"],"shuttered-manse":["คฤหาสน์ปิดตาย","นางรู้สึกว่าโจรรายนั้นใกล้เข้ามาในทุกก้าวที่เขาเดินด้วยความระแวดระวัง"],"udyr-color-story":["ก้าวเคียงสรรพเสียง","อูเดียร์ได้ยินเสียงร้องของนกอินทรีเหินเวหาลอยลมดังมาจากด้านบนสูงขึ้นไป เสียงของมันทั้งมีพลังเข้มแข็งและเปี่ยมความมั่นใจ แต่ไม่อาจแทรกเข้ามาในห้วงความคิดของเขาได้ การสัมผัสได้ถึงมนุษย์ผู้นี้ทำให้รู้สึกโล่งใจ"],"ziggs-color-story":["ระเบิดส่งท้าย","เอาล่ะ ซอนจ๋า ฉันอยู่นี้แล้ว ฉันคือปุกปุยจอมป่วน แล้วฉันก็พร้อมจะระเบิดข้าวของให้เปรี้ยงปร้าง"],"seraphine-color-story":["มีเพียงที่ยืน","ซอนและพิลโทเวอร์ขับขานสู่กันและกัน ท่อนวนซ้ำของบทเพลงนั้นเต็มไปด้วยบาดแผลเก่า ความอยุติธรรมและความเจ็บปวด ฉันคิดว่ามีแต่ฉันเท่านั้นที่ได้ยินมัน แต่ที่จริงแล้วพวกเราทุกคนรู้สึกถึงมัน เสียงฮัมนั้นผสมอยู่ในฉากหลังของชีวิตประจำวันที่ดำเนินไปและผลักทั้งชาวซอนและชาวพิลโทเวอร์ให้เบาะแว้งโหวกเหวก"],"the-host":["โฮสต์","ข้ากำลังจะตาย"],"proclamation-of-the-trifarix":["แถลงการณ์แห่งไทฟาริกซ์","ปวงประชาแห่งน็อกซัส ข้ามีประกาศจากนครหลวงมาแจ้งให้ทราบโดยทั่วกัน!"],"vladimir-color-story":["เดียวดาย","ลิเวียจวนจะหลับแล้วเมื่อตอนที่แสงสว่างปรากฏขึ้น"],"rell-color-story":["หลุมศพที่สอง","เรลล์นึกถึงพวกผู้สูญพลังอยู่บ่อยครั้ง"],"gragas-color-story":["ทิปจัดหนัก","สูงขึ้นไปบนเทือกเขาที่เป็นเส้นแบ่งแยกพรมแดนระหว่างเดมาเซียและเฟรย์ลยอร์ดนั้น งานที่จ่ายค่าตอบแทนเป็นเงินให้ไม่ได้มีมากนัก งานบางอย่างจ่ายค่าตอบแทนเป็นขนสัตว์ หรือไม่ก็ขนมปังครึ่งแถวที่ทั้งเย็นและแข็งเป๊ก... แต่น้องสาวตัวน้อยของอีจิลที่ป่วยกระเสาะกระแสะตั้งแต่เกิด ครอบครัวของเขาต้องใช้เงินเพื่อให้นางมีอาหารและหยูกยาที่จำเป็น"],"redeemed":["ไถ่บาป","เซนน่าตื่นขึ้นมาพร้อมหอบเฮือก ลมหายใจของนางแลเห็นเป็นไอท่ามกลางอากาศเย็นยะเยือกของยามราตรี ทั้งแขน ขา ลำคอ และแผ่นหลังของนางเปียกเหงื่อโซมและมีเศษทรายเกาะ ความคิดหนึ่งผุดขึ้นในใจของนาง"],"viego-color-story":["เพื่อนาง","แต่ละครั้งที่วิเอโก้นึกถึงใบหน้านาง ใบหน้านั้นจะดูแตกต่างกันไปเล็กน้อย"],"teeth":["ดงคมเขี้ยว","ไม้ฟืนถือเป็นของล้ำค่าในดินแดนทะเลทราย แต่ซากสิ่งปลูกสร้างที่ดำเป็นตอตะโกของเวเคาร่านั้นมีท่อนไม้ไหม้เกรียมมากมายให้โยนใส่กองไฟกลางแจ้ง เมื่อตอนที่พวกแซนด์แธรชเชอร์ขี่สัตว์พาหนะผ่านซากกำแพงเมืองเข้ามา เมืองแห่งนี้อยู่ในสภาพซากปรักหักพังจากแรงระเบิด ท้องถนนว่างเปล่า ร้างไร้ชาวเมือง"],"finishing-soates":["ตอนอวสานของโซเอทีส","ทาร์โนลด์รู้ดีว่าการแสดงเป็นอันต้องพานพบความพินาศเมื่อกลเม็ดการประพันธ์บทละครอันแพรวพราวของเขาถูกงัดออกมาใช้จนหมดเกลี้ยง นักแสดงของเขาพากันตื่นเวทีสมาธิกระเจิง อาจจะเป็นเพราะบท หรือไม่ก็เพราะความเชื่องมงายเกี่ยวกับอาถรรพ์จากการนำบทละครที่ผู้ประพันธ์เสียชีวิตก่อนจะแต่งจบมาใช้แสดงก็ได้ แต่นักแสดงแต่ละรายล้วนขาดความเป็นมืออาชีพไม่ในด้านใดก็ด้านหนึ่ง"],"gwen-color-story":["ช่างเย็บผ้าพเนจร","ใต้ดวงอาทิตย์ที่กำลังคล้อยต่ำ หญิงสาวผู้หนึ่งยืนซ่อนอยู่หลังดงไม้หนา ผมของนางเป็นสีฟ้าเหลือบเงินและมีโบสีดำอันใหญ่ติดไว้เสริมแต่งพร้อมเครื่องประดับสีทองที่เข้ากับชุดที่ตัดเย็บประณีตหรูหรา ในมือของนางมีกรรไกรขนาดยักษ์ที่ดูเรืองตา เป็นเวลาหลายสัปดาห์หรืออาจจะหลายเดือนแล้วนับจากวันแรกที่นางเดินทางมาถึงทวีปตะวันตกแห่งนี้ อาณาเขตของผืนแผ่นดินนี้ยาวไกลจรดขอบฟ้า กว้างใหญ่ไพศาลกว่าดินแดนใดที่นางเคยพบเห็น แต่มีสิ่งหนึ่งที่ค้างคาอยู่ในใจของเกว็น"],"to-herd-a-cat":["วิธีจับแมวใส่กระด้ง","\"ในที่สุด ฉันก็จะได้แสดงให้ทุกคนเห็นความสามารถที่แท้จริงของฉันแล้ว\""],"medikul-jernel":["บันทุกทางกานแพดของมุนโด้","เนื้อหาบางส่วนได้มีการปรับภาษาให้สามารถอ่านเข้าใจได้และตรวจแก้ไวยากรณ์โดย John O'Bryan"],"in-sight-of-land":["In Sight of Land","The waters were eerily still at night. Their surface was so undisturbed, one might mistake it for dark glass mirroring the starlit skies above. Moonlight bathed everything in cold, silver light, though its radiance was slowly dying."],"despoiler-of-havenfall":["ผู้ก่อความพินาศแห่งเฮเวนฟอล","หมอกเคลื่อนรุดหน้ามาอย่างรวดเร็วและบดบังดวงอาทิตย์ยามบ่ายที่ลอยอยู่เหนือสี่แยกนั้น โจนัธพยายามเดินทางต่อไปท่ามกลางดงหมอกหนา โลกรอบตัวเขามืดลงด้วยฤทธิ์แห่งม่านหมอกที่ไม่อาจแหวกฝ่า รูปทรงหลากหลายดันผลักผืนหมอกและไขว่คว้าเกาะกุม เอื้อมยืดหมายจับเขาจากอีกฟากหนึ่ง"],"akshan-color-story":["ค้นหาสิ่งที่สูญหาย","ชัดญ่าเพิ่งตายไปได้เพียงไม่กี่สัปดาห์ แต่ Akshan กลับรู้สึกว่าร่องรอยทุกอย่างเกี่ยวกับนางกำลังจางหายไป นั่นเป็นสิ่งที่ยากที่สุดสำหรับเรื่องเศร้าของเขาในครั้งนี้ิ ทั้งการสะสมของที่ระลึกไว้ดูต่างหน้า และการขวนขวายรวบรวมอะไรก็ตามที่เกี่ยวข้องกับอาจารย์สุดที่รักของเขาที่ยังหลงเหลืออยู่"],"spirit-of-copperwood-glade-story":["วิญญาณแห่งคอปเปอร์วูด เกลด","ในยุคมืดหม่นเช่นนี้ เป็นเรื่องธรรมดาที่จะเอ่ยถึงเอลเดอร์วูดด้วยความยกย่องเชิดชูระดับหนึ่ง เพราะทั้งคนรุ่นเยาว์และผู้เฒ่าผู้แก่ต่างรู้ดีว่ามันคือแดนมหันตภัยที่เต็มไปด้วยกลลวงและกับดักซึ่งวางไว้โดยทายาทที่แท้จริงกลุ่มสุดท้ายแห่งแดนพงไพร"],"the-dissonant-verses":["บทขับขานแห่งดิสโซแนนซ์ 1: ปฐมบทแห่งเทพเจ้าต้องห้าม","\"พวกโง่!\""],"vex-color-story":["ความหมายในความทุกข์ยาก","It was midday on the island, and Vex was just emerging from her previous night’s sleep. The Black Mist that blanketed the Shadow Isles was especially thick today, creating an atmosphere of despondency that suited her perfectly."],"bard-color-story":["คำยืนยันจากนักขับขาน","เจ้าที่อยู่ตรงนั้นน่ะ! เออ เจ้านั่นล่ะ! เจ้าดูท่าจะเป็นชาวเดมาเซียที่หูสองข้างใช้การได้ แถมยังน่าจะมีเวลาและใส่ใจฟังคำเตือนจากชายชราผู้เคยพบสิ่งอันอัศจรรย์เกินกว่าจะเป็นจริง ข้ากำลังอยู่ระหว่างทำภารกิจที่ได้รับมอบหมายจาก เอ่อ ทูตสวรรค์พเนจร แล้วเจ้าก็ช่วยข้าได้!!"],"fragile-legacies":["มรดกอันเปราะบาง","I was young and unafraid, heart aflame with the sort of righteousness that cast out all shadows of doubt, on the day I first met Barrett Buvelle."],"the-face-in-her-stars":["ใบหน้าของเจ้าในดวงดาวของนาง","Under the heat of the midday sun, my opponent and I circled one another."],"feast-of-the-prophet":["งานเลี้ยงของศาสดาพยากรณ์","เมียร์ตามกลุ่มผู้สังกัดลัทธิออกจากเมืองกระโจมของศาสดาพยากรณ์ แล้วเดินลงสู่หุบเขาลึกที่ขอบทะเลทราย"],"dead-of-winter":["ความหนาวเหน็บแห่งเหมันต์","เซจัวนี่มองเห็นว่าแมมมอธกำลังจะสิ้นลมได้แม้จากที่ไกล..."],"sejuani-color-story":["เงื่อนพลีชีพ","เซจัวนี่เหวี่ยงขวานสับลงไปบนลำต้นของต้นไม้ นางต้องออกแรงสับถึงห้าครั้งกว่าจะล้มต้นไม้นั้นได้สำเร็จ และการโค่นต้นไม้นับสิบก็ทำเอานางถึงกับเหนื่อยหอบ พวกไอซ์บอร์นนั้นจะแข็งแกร่งที่สุดเมื่ออยู่ในสภาพแวดล้อมที่หนาวเย็น และความร้อนของแดนใต้ก็สูบพละกำลังของนางให้ถดถอยลงไป"],"the-faceless-god":["เทพผู้ไร้ใบหน้า","ข้ามองดูเจ้าหนอนดีดดิ้นขึ้นมาจากผืนทราย หัวที่เหมือนใบไม้ของมันส่ายไปมาขณะที่มันลิ้มรสอากาศ..."],"hollowspun":["ฮอลโลว์สปัน","ไค’สะชะโงกออกมาจากปากอุโมงค์และรู้สึกราวกับว่านางกำลังยืนอยู่ที่ขอบโลก"],"in-battle-broken":["บอบช้ำกรำศึก","หลังจากทำงานทั้งวันจนเหนื่อยล้า ยูล่ายกมือที่ด้านแข็งของนางเช็ดผ้ากันเปื้อนและหยิบถ้วยใบหนึ่งชูขึ้นไปทางแท่นเหนือเตาผิง"],"zeri-color-story":["ประกายไฟที่ไม่คาดคิด","\"ข้ารับไว้ไม่ได้หรอก\" เจ้าของร้านเอ่ยและดันเหรียญของเซริคืนกลับไป..."],"renataglasc-color-story":["ตรงเวลา","ส้นรองเท้าของเรนาต้า กลาสค์กระทบกับพื้นหินอ่อนจนส่งเสียงดังลั่นเมื่อเธอเดินไปที่ประตูหน้าคฤหาสน์ ทางเดินนี้ช่างยาวไกล"],"stranger-on-the-road":["ชายแปลกหน้าบนถนน","ถนนจากเทนาซิตี้สู่โพรเกรสเป็นเส้นทางที่เรียบและแห้งแล้ง มีแต่กระบองเพชรจากฟากหนึ่งสู่อีกฟากหนึ่งของเส้นทางยาวหลายไมล์..."],"the-eyes-and-the-embers":["ดวงตาและเถ้าถ่าน","วิ่ง"],"belveth-color-story":["ดั่งกังหัน","“เอาล่ะ” ไค’สะหายใจหอบ และมองไปที่รูปร่างที่กำลังเติบโตเบื้องหน้า เบื้องบน และรอบ ๆ ตัวเธอไปพร้อมกัน..."],"the-boys-and-bombolini":["หนุ่ม ๆ และบอมโบลินี","ณ ที่แห่งหนึ่ง ท่ามกลางบรรดาโกดังเก็บของแสนโสโครกในบิลจ์วอเตอร์ที่เต็มไปด้วยมีดเก่าขึ้นสนิมและหนูกินเนื้อขนาดตัวเท่าแขน กลับมีโกดังเก็บของแห่งหนึ่งที่ไร้ซึ่งสิ่งที่กล่าวมาอย่างสิ้นเชิง..."],"star-guardian-twin-stars":["ดาวคู่แฝด","อาคาลิมองเห็นดวงดาวเด่นชัด พวกมันส่องประกายอยู่เหนือหัวเธอ แต่ละดวงส่องสว่างไสวดั่งเปลวไฟที่ประดับประดาท้องฟ้าเมืองวาโรแลน"],"nilah-color-story":["ยามเย็นชวนอิ่มเอม ณ ออยสเตอร์บิล","เจ้าจะได้รู้จักความปีติ เจ้าจะได้เป็นวีรชน เจ้าจะได้กลายเป็นตำนานเฉกเช่นเหล่าวีรชนผู้ยิ่งใหญ่ในอดีต"],"ruination-prologue":["บทนำนิยาย Ruination","เออร์ลอค กราเอลยืนแยกตัวอยู่ห่างจากคนอื่น ๆ รอเวลาแห่งการถูกเลือกอยู่ลำพัง..."],"ksante-color-story":["สิ่งที่เราควรจะพูดไป","เค’ซานติยกมือขึ้นปัดหน้าผาก นิ้วเปื้อนเลือดของเขาเปรอะเปื้อนไปด้วยหยาดเหงื่อและเศษดิน..."],"milios-reports":["รายงานการผจญภัยสุดพิเศษของมิลิโอ","ว่าไงทุกคน! มิลิโอเองนะ และนี่ก็คือรายงานการผจญภัยอย่างเป็นทางการครั้งแรกของข้า!"],"paintings-framed-in-half-light":["ภาพผลงานท่ามกลางแสงสายัณห์","ภาพนิมิตถาโถม"],"leblanc-everywhere-and-everyone":["ทุกหนแห่ง และทุกคน","\"ช่างน่าเหลือเชื่อ ที่ท่านนายพลไม่แม้แต่จะกรีดร้องให้กับความเจ็บปวดเลยสักครั้ง\""]};
